    23	func TestConcurrentFactCommitsAreLossless(t *testing.T) {
    24		brainDir := t.TempDir()
    25		branch := "main"
    26		now := time.Date(2026, 6, 8, 12, 0, 0, 0, time.UTC)
    27		const workers = 32
    28		makeFact := func(text string, paths []string, at time.Time) factRecord {
    29			p := normalizeFactPaths(paths)
    30			return factRecord{
    31				ID:        factRecordID(text, p),
    32				Paths:     p,
    33				Text:      text,
    34				Branch:    branch,
    35				Origin:    factOriginDistilled,
    36				Status:    factStatusActive,
    37				CreatedAt: at,
    38				UpdatedAt: at,
    39			}
    40		}
    41	
    42		start := make(chan struct{})
    43		errs := make(chan error, workers)
    44		var wg sync.WaitGroup
    45		for i := 0; i < workers; i++ {
    46			i := i
    47			wg.Add(1)
    48			go func() {
    49				defer wg.Done()
    50				<-start
    51				unique := makeFact(fmt.Sprintf("unique fact %02d", i), []string{"project.tooling.stack"}, now.Add(time.Duration(i)*time.Second))
    52				unique.Provenance = []factAnchor{{SessionID: fmt.Sprintf("unique-%02d", i), Line: i + 1}}
    53				shared := makeFact("shared fact", []string{"preferences.coding.style"}, now)
    54				shared.Provenance = []factAnchor{{SessionID: fmt.Sprintf("shared-%02d", i), Line: i + 1}}
    55				errs <- withBrainWriteLockForLosslessConcurrencyTest(brainDir, func() error {
    56					facts, err := loadFacts(brainDir, branch)
    57					if err != nil {
    58						return err
    59					}
    60					facts = upsertFact(facts, unique)
    61					facts = upsertFact(facts, shared)
    62					if err := writeFacts(brainDir, branch, facts); err != nil {
    63						return err
    64					}
    65					return updateFactSourceManifestLocked(brainDir, now)
    66				})
    67			}()
    68		}
    69		close(start)
    70		wg.Wait()
    71		close(errs)
    72		for err := range errs {
    73			if err != nil {
    74				t.Fatalf("concurrent commit: %v", err)
    75			}
    76		}
    77	
    78		facts, err := loadFacts(brainDir, branch)
    79		if err != nil {
    80			t.Fatalf("load facts: %v", err)
    81		}
    82		if got, want := len(facts), workers+1; got != want {
    83			t.Fatalf("facts len = %d, want %d: %+v", got, want, facts)
    84		}
    85		ids := map[string]factRecord{}
    86		for _, fact := range facts {
    87			if _, exists := ids[fact.ID]; exists {
    88				t.Fatalf("duplicate fact id on disk: %s", fact.ID)
    89			}
    90			ids[fact.ID] = fact
    91		}
    92		sharedID := factRecordID("shared fact", normalizeFactPaths([]string{"preferences.coding.style"}))
    93		shared, ok := ids[sharedID]
    94		if !ok {
    95			t.Fatalf("shared fact missing")
    96		}
    97		if got := len(shared.Provenance); got != workers {
    98			t.Fatalf("shared provenance len = %d, want %d: %+v", got, workers, shared.Provenance)
    99		}
   100		for i := 0; i < workers; i++ {
   101			id := factRecordID(fmt.Sprintf("unique fact %02d", i), normalizeFactPaths([]string{"project.tooling.stack"}))
   102			if _, ok := ids[id]; !ok {
