   138		// in the lexical arm gives the semantically-near invariant a second,
   139		// independent retrieval signal instead of leaving it just outside the packet.
   140		if terms := historyQueryTerms(query); !slices.Contains(terms, "before") {
   141			t.Fatalf("temporal constraint term was discarded: %v", terms)
   142		}
