    33	// TestFactsPromoteValidatesBothBranchEndpoints is the regression for a promote
    34	// that checked --strategy, a missing --from and self-promotion but never once
    35	// asked whether the branch names it was handed meant anything.
    36	//
    37	// Both halves failed silently, and the --into half destroyed data:
    38	// writeFacts creates the target store on demand, so a typo forked the fact set
    39	// into a directory keyed to a branch that does not exist. No branch can reach
    40	// it, no command names it, and promote reported success — the facts were gone.
    41	func TestFactsPromoteValidatesBothBranchEndpoints(t *testing.T) {
    42		t.Run("unknown --from is refused", func(t *testing.T) {
    43			f, _ := promoteFixtureWithSourceFacts(t)
    44			out, err := execute(t, NewRootCommand(f.opts), "facts", "promote", "--from", "no-such-branch", "--strategy", "keep-both")
    45			if err == nil {
    46				t.Fatalf("promoting from a branch that does not exist succeeded:\n%s", out)
    47			}
    48			if !strings.Contains(err.Error(), "--from") || !strings.Contains(err.Error(), "no-such-branch") {
    49				t.Fatalf("refusal should name --from and the branch, got: %v", err)
    50			}
    51		})
    52	
    53		t.Run("unknown --into is refused and strands no store", func(t *testing.T) {
    54			f, _ := promoteFixtureWithSourceFacts(t)
    55			const bogus = "totally/bogus/branch"
    56	
    57			out, err := execute(t, NewRootCommand(f.opts), "facts", "promote", "--from", "feature", "--into", bogus, "--strategy", "prefer-target")
    58			if err == nil {
    59				t.Fatalf("promoting into a branch that does not exist succeeded:\n%s", out)
    60			}
    61			if !strings.Contains(err.Error(), "--into") || !strings.Contains(err.Error(), bogus) {
    62				t.Fatalf("refusal should name --into and the branch, got: %v", err)
    63			}
    64	
    65			// The orphan store is the damage: it must never have been written.
    66			if factBranchStoreExists(f.storage.BrainDir, bogus) {
    67				t.Fatalf("refused promote still wrote a fact store for %q", bogus)
    68			}
    69			orphanDir := filepath.Join(f.storage.BrainDir, filepath.FromSlash(factsBranchRelDir(bogus)))
    70			if _, statErr := os.Stat(orphanDir); statErr == nil {
    71				t.Fatalf("refused promote still created the branch directory %s", orphanDir)
    72			}
    73		})
    74	
    75		t.Run("a real --from with no facts says so instead of reporting success", func(t *testing.T) {
    76			f, _ := promoteFixtureWithSourceFacts(t)
    77			out, err := execute(t, NewRootCommand(f.opts), "facts", "promote", "--from", "empty", "--strategy", "keep-both")
    78			if err == nil {
    79				t.Fatalf("promoting from a branch with no facts reported success:\n%s", out)
    80			}
    81			if !strings.Contains(err.Error(), "no facts to promote") {
    82				t.Fatalf("an empty source should be named as such, got: %v", err)
    83			}
    84		})
    85	
    86		t.Run("a valid promote still works", func(t *testing.T) {
    87			f, fact := promoteFixtureWithSourceFacts(t)
    88			out, err := execute(t, NewRootCommand(f.opts), "facts", "promote", "--from", "feature", "--strategy", "keep-both")
    89			if err != nil {
    90				t.Fatalf("valid promote was refused: %v\n%s", err, out)
