    92			if !strings.Contains(out, "promoted 1 fact(s) from feature into main") {
    93				t.Fatalf("unexpected promote summary:\n%s", out)
    94			}
    95			facts, loadErr := loadFacts(f.storage.BrainDir, "main")
    96			if loadErr != nil {
    97				t.Fatal(loadErr)
    98			}
    99			if indexOfFact(facts, fact.ID) < 0 {
   100				t.Fatalf("promoted fact did not land on main: %+v", facts)
