   133	// TestFactsReviewRefusesContradictoryFlags is the regression for a resolver
   134	// whose switch tested apply before reject: asking it to both apply and reject
   135	// the same proposal settled the apply half, dropped the reject half without a
   136	// word, and reported "resolved 1 proposal(s)". The user was told a decision
   137	// landed while the opposite one actually did.
   138	func TestFactsReviewRefusesContradictoryFlags(t *testing.T) {
   139		newFixture := func(t *testing.T) (verifyFixture, factProposal) {
   140			t.Helper()
   141			f := newVerifyFixture(t)
   142			paths := normalizeFactPaths([]string{"ops.deploy.strategy"})
   143			target := factRecord{
   144				ID: factRecordID("deploys use blue-green cutover", paths), Paths: paths,
   145				Text: "deploys use blue-green cutover", Branch: "main", Origin: factOriginDistilled,
   146				Status: factStatusActive, CreatedAt: f.now, UpdatedAt: f.now,
   147			}
   148			candidate := factRecord{
   149				ID: factRecordID("deploys use in-place rolling restart", paths), Paths: paths,
   150				Text: "deploys use in-place rolling restart", Branch: "main", Origin: factOriginDistilled,
   151				Status: factStatusActive, CreatedAt: f.now, UpdatedAt: f.now,
   152			}
   153			f.writeFacts(t, "main", []factRecord{target, candidate})
   154			proposal := factProposal{
   155				Action: factActionSupersede, CandidateID: candidate.ID, TargetID: target.ID, Branch: "main",
   156			}
   157			if err := writeFactProposals(f.storage.BrainDir, "main", []factProposal{proposal}); err != nil {
   158				t.Fatal(err)
   159			}
   160			return f, proposal
   161		}
   162	
   163		// One proposal, and every way of asking for it to be settled two ways at once.
   164		contradictions := func(id string) map[string][]string {
   165			return map[string][]string{
   166				"apply and reject the same id": {"--apply", id, "--reject", id},
   167				"apply-all and reject-all":     {"--apply-all", "--reject-all"},
   168				"apply-all and reject an id":   {"--apply-all", "--reject", id},
   169				"reject-all and apply an id":   {"--reject-all", "--apply", id},
   170			}
   171		}
   172	
   173		f, proposal := newFixture(t)
   174		for name, flags := range contradictions(proposal.CandidateID) {
   175			t.Run(name, func(t *testing.T) {
   176				f, proposal := newFixture(t)
   177				args := append([]string{"facts", "review"}, flags...)
   178				out, err := execute(t, NewRootCommand(f.opts), args...)
   179				if err == nil {
   180					t.Fatalf("contradictory flags were accepted:\n%s", out)
   181				}
   182	
   183				// A refusal must be total: the queue and the facts stay as they were,
   184				// so the caller can re-run with the half they meant.
   185				queued, qErr := loadFactProposals(f.storage.BrainDir, "main")
   186				if qErr != nil {
   187					t.Fatal(qErr)
   188				}
   189				if len(queued) != 1 || queued[0].CandidateID != proposal.CandidateID {
   190					t.Fatalf("refused review still settled the queue: %+v", queued)
   191				}
   192				facts, loadErr := loadFacts(f.storage.BrainDir, "main")
   193				if loadErr != nil {
   194					t.Fatal(loadErr)
   195				}
   196				for _, fact := range facts {
   197					if fact.Status != factStatusActive {
   198						t.Fatalf("refused review still mutated facts: %+v", fact)
   199					}
   200				}
   201			})
   202		}
   203	
   204		// The control: one side alone still settles, so the refusal is about the
   205		// contradiction and not about the flags themselves.
   206		out, err := execute(t, NewRootCommand(f.opts), "facts", "review", "--apply", proposal.CandidateID)
   207		if err != nil {
   208			t.Fatalf("a single --apply should still work: %v\n%s", err, out)
   209		}
   210		if !strings.Contains(out, "resolved 1 proposal(s)") {
   211			t.Fatalf("unexpected review summary:\n%s", out)
   212		}
   213	}
