   156	func TestRetractFact(t *testing.T) {
   157		now := time.Date(2026, 6, 5, 12, 0, 0, 0, time.UTC)
   158		a := factFor(t, "active fact", []string{"project.tooling.stack"}, now)
   159		facts := []factRecord{a}
   160	
   161		found, changed := retractFact(facts, a.ID, now.Add(time.Hour))
   162		if !found || !changed {
   163			t.Fatalf("expected found+changed, got found=%v changed=%v", found, changed)
   164		}
   165		if facts[0].Status != factStatusRetracted || !facts[0].UpdatedAt.Equal(now.Add(time.Hour)) {
   166			t.Fatalf("fact not retracted/stamped: %+v", facts[0])
   167		}
   168		// Retracting again is a no-op (found, not changed).
   169		found, changed = retractFact(facts, a.ID, now.Add(2*time.Hour))
   170		if !found || changed {
   171			t.Fatalf("re-retract should be found-but-unchanged, got found=%v changed=%v", found, changed)
   172		}
   173		// Unknown id.
   174		if found, _ := retractFact(facts, "fact:nope", now); found {
   175			t.Fatalf("unknown id should not be found")
   176		}
   177		// A retracted fact drops out of active recall and gc prunes it.
   178		if got := rankFacts(facts, "", 10, false); len(got) != 0 {
   179			t.Fatalf("retracted fact should not surface in active recall")
   180		}
   181		res := gcFacts(facts, defaultFactTaxonomy(now), now, defaultFactRetention)
   182		if len(res.Pruned) != 1 || len(res.Kept) != 0 {
   183			t.Fatalf("gc should prune the retracted fact: %+v", res)
   184		}
   185	}
