   190		retracted := factFor(t, "retracted", []string{"project.tooling.stack"}, now)
   191		retracted.Status = factStatusRetracted
   192		oldSuperseded := factFor(t, "old superseded", []string{"project.tooling.stack"}, now.Add(-60*24*time.Hour))
   193		oldSuperseded.Status = factStatusSuperseded
   194		recentSuperseded := factFor(t, "recent superseded", []string{"project.tooling.stack"}, now.Add(-1*24*time.Hour))
   195		recentSuperseded.Status = factStatusSuperseded
   196		orphan := factFor(t, "orphan", []string{"project.tooling.stack"}, now)
   197		orphan.Paths = []string{"gone.sub.type"} // top-level not in taxonomy
   198	
   199		tax := defaultFactTaxonomy(now)
   200		result := gcFacts([]factRecord{active, retracted, oldSuperseded, recentSuperseded, orphan}, tax, now, defaultFactRetention)
   201	
   202		if len(result.Pruned) != 2 {
   203			t.Fatalf("expected retracted + old-superseded pruned (2), got %d", len(result.Pruned))
   204		}
   205		if len(result.Orphans) != 1 || result.Orphans[0].Text != "orphan" {
   206			t.Fatalf("expected 1 reported orphan, got %d", len(result.Orphans))
   207		}
   208		// Orphan is active and not old → kept (orphans are never auto-deleted).
   209		if indexOfFact(result.Kept, orphan.ID) < 0 {
   210			t.Fatalf("active orphan should be kept, not pruned")
   211		}
   212		if indexOfFact(result.Kept, recentSuperseded.ID) < 0 {
   213			t.Fatalf("recent superseded should be retained within the window")
