 15	func TestEvalMetricsLabeled(t *testing.T) {
 16		surfaced := []factRecord{
 17			{ID: "a", Text: "relevant fact one", Paths: []string{"p.q.r"}},
 18			{ID: "b", Text: "irrelevant", Paths: []string{"p.q.r"}},
 19			{ID: "c", Text: "relevant fact two", Paths: []string{"p.q.r"}},
 20		}
 21		relevant := map[string]struct{}{"a": {}, "c": {}, "d": {}} // d not surfaced
 22		res := evalMetrics(surfaced, relevant, len(relevant))
 23	
 24		if res.RelevantSurfaced != 2 {
 25			t.Fatalf("relevant surfaced = %d, want 2", res.RelevantSurfaced)
 26		}
 27		if res.Precision != 2.0/3.0 {
 28			t.Errorf("precision = %v, want 0.667", res.Precision)
 29		}
 30		if res.Recall != 2.0/3.0 {
 31			t.Errorf("recall = %v, want 0.667 (2 of 3 relevant)", res.Recall)
 32		}
 33		if res.Tokens <= 0 {
 34			t.Errorf("tokens should be > 0")
 35		}
 36		// useful/1k = relevant(2) / (tokens/1000)
 37		want := 2.0 / (float64(res.Tokens) / 1000.0)
 38		if res.UsefulPer1k != want {
 39			t.Errorf("useful/1k = %v, want %v", res.UsefulPer1k, want)
 40		}
 41	}
