 43	func TestEstimateTokensMonotonic(t *testing.T) {
 44		few := []factRecord{{Text: "short", Paths: []string{"a.b.c"}}}
 45		more := append([]factRecord(nil), few...)
 46		more = append(more, factRecord{Text: "a considerably longer fact statement here", Paths: []string{"a.b.c"}})
 47		if estimateTokens(more) <= estimateTokens(few) {
 48			t.Fatalf("more facts should estimate more tokens")
 49		}
 50		if estimateTokens(nil) != 0 {
 51			t.Fatalf("empty should be 0 tokens")
 52		}
 53	}
