 55	func TestParseJudgeOutput(t *testing.T) {
 56		facts := []factRecord{{ID: "a"}, {ID: "b"}, {ID: "c"}}
 57		out := "1 yes\n2 no\n3 YES\ngarbage\n9 yes" // 9 out of range, garbage skipped
