 73	func TestRunFactsEvalLabeledAndJudge(t *testing.T) {
 74		brainDir := t.TempDir()
 75		now := time.Date(2026, 6, 5, 12, 0, 0, 0, time.UTC)
 76		mk := func(text, path string) factRecord {
 77			p := normalizeFactPaths([]string{path})
 78			return factRecord{ID: factRecordID(text, p), Paths: p, Text: text, Branch: "main", Status: factStatusActive, UpdatedAt: now}
 79		}
 80		f1 := mk("Checkpoints v1.1 read from a custom local ref", "architecture.data.flow")
 81		f2 := mk("The project uses Go modules", "project.tooling.stack")
