 83			t.Fatal(err)
 84		}
 85	
 86		// Labeled task: only f1 is relevant.
 87		tasks := []evalTask{{ID: "t1", Task: "checkpoints v1.1 read ref", Branch: "main", Relevant: []string{f1.ID}, LabelSource: evalLabelSourceHuman}}
 88		res, err := runFactsEval(context.Background(), Options{}, brainDir, "/repo", "main", tasks, 10, false, nil, nil, loadJudgeCache(""), nil, nil, evalRetrieverFacts)
 89		if err != nil {
 90			t.Fatalf("runFactsEval: %v", err)
 91		}
 92		if len(res) != 1 || !res[0].Labeled {
 93			t.Fatalf("expected one labeled result, got %+v", res)
 94		}
 95		if res[0].RelevantSurfaced != 1 {
 96			t.Fatalf("expected f1 surfaced and counted, got %+v", res[0])
 97		}
 98		if res[0].RelevanceSource != evalRelevanceExplicitLabel {
 99			t.Fatalf("labeled eval relevance source = %q, want %q", res[0].RelevanceSource, evalRelevanceExplicitLabel)
100		}
101		if res[0].LabelSource != evalLabelSourceHuman {
102			t.Fatalf("label source = %q, want %q", res[0].LabelSource, evalLabelSourceHuman)
103		}
104	
105		silverTasks := []evalTask{{ID: "silver", Task: "checkpoints v1.1 read ref", Branch: "main", Relevant: []string{f1.ID}, LabelSource: evalLabelSourceProvenanceSilver}}
106		silver, err := runFactsEval(context.Background(), Options{}, brainDir, "/repo", "main", silverTasks, 10, false, nil, nil, loadJudgeCache(""), nil, nil, evalRetrieverFacts)
107		if err != nil {
108			t.Fatalf("runFactsEval silver: %v", err)
109		}
110		if len(silver) != 1 || silver[0].Labeled || silver[0].Recall != 0 {
111			t.Fatalf("silver labels must not count as proof labels: %+v", silver)
112		}
113		if silver[0].RelevanceSource != evalRelevanceSilverLabel || silver[0].LabelSource != evalLabelSourceProvenanceSilver {
114			t.Fatalf("silver label metadata wrong: %+v", silver[0])
115		}
116	
117		// Judge mode: fake agent marks the first surfaced fact relevant.
118		fakeRun := func(ctx context.Context, dir string, args []string, input []byte, timeout time.Duration) (string, error) {
119			return "1 yes\n", nil
120		}
121		tasksJ := []evalTask{{ID: "t2", Task: "checkpoints", Branch: "main"}}
122		resJ, err := runFactsEval(context.Background(), Options{}, brainDir, "/repo", "main", tasksJ, 10, true, fakeRun, []string{"fake"}, loadJudgeCache(""), nil, nil, evalRetrieverFacts)
123		if err != nil {
124			t.Fatalf("runFactsEval judge: %v", err)
125		}
126		if resJ[0].Labeled {
127			t.Errorf("judge result should not be marked labeled")
128		}
129		if resJ[0].RelevantSurfaced != 1 {
130			t.Errorf("judge should have marked one fact relevant, got %d", resJ[0].RelevantSurfaced)
131		}
132		if resJ[0].RelevanceSource != evalRelevanceJudge {
133			t.Errorf("judge relevance source = %q, want %q", resJ[0].RelevanceSource, evalRelevanceJudge)
134		}
135		if resJ[0].UsefulPer1k <= 0 {
136			t.Errorf("useful/1k should be > 0 when a fact was judged relevant")
137		}
138	}
