    66	// The public oracle and manual judgments are committed benchmark inputs. The
    67	// additional phrasings below are explicitly synthetic regressions, not new
    68	// judgments: they preserve the oracle's hook-wrapper intent while exercising
    69	// identifier punctuation and the committed fact's cmd.exe locus.
    70	func REDACTED(t *testing.T) {
    71		facts := loadFactsBM25PublicSnapshot(t)
    72		const target = "fact:30c6c2e4a031d91df16e4d27"
    73		const hardDistractor = "fact:32a34f711bb107845dc407c3"
    74		for _, query := range []string{
    75			factsBM25PublicOracleQuery,
