    77			"cmd.exe sh wrapper reinstall",
    78		} {
    79			scores, ok := factsFTSScores(facts, query)
    80			if !ok {
    81				t.Fatalf("BM25 unavailable for %q", query)
    82			}
    83			targetRank := factsBM25Rank(scores, target)
    84			distractorRank := factsBM25Rank(scores, hardDistractor)
    85			if targetRank != 1 {
    86				t.Fatalf("query %q: solving fact rank=%d, want 1", query, targetRank)
    87			}
    88			if distractorRank > 0 && distractorRank <= targetRank {
    89				t.Fatalf("query %q: hard distractor rank=%d must remain below solving rank=%d", query, distractorRank, targetRank)
    90			}
    91		}
