    94	// These queries are exact locus values from the committed public snapshot, so
    95	// the owning fact is an intrinsic address target rather than a new manual
    96	// relevance judgment. Together they cover punctuation, path-like identifiers,
    97	// and the top-10 boundary that the previous text+taxonomy-only index missed.
    98	func TestFactsBM25PublicLocusScenarios(t *testing.T) {
    99		facts := loadFactsBM25PublicSnapshot(t)
   100		for _, scenario := range []struct {
   101			query   string
   102			target  string
   103			maxRank int
   104		}{
   105			{query: "git/config", target: "fact:11af406c1bcd1c4994261a6c", maxRank: 2},
   106			{query: "branch/push", target: "fact:86eeae1918bb7aa4eca19306", maxRank: 1},
   107			{query: "user/repository", target: "fact:9c39a262ba60f7ed28023b46", maxRank: 1},
   108			{query: "/api/v1/me/recap", target: "fact:b492d36505d004ee3f331cc1", maxRank: 1},
   109			{query: "entire/sessions", target: "fact:d939db93c090d7ab800329a0", maxRank: 10},
   110		} {
   111			scores, ok := factsFTSScores(facts, scenario.query)
   112			if !ok {
   113				t.Fatalf("BM25 unavailable for %q", scenario.query)
   114			}
   115			if rank := factsBM25Rank(scores, scenario.target); rank == 0 || rank > scenario.maxRank {
   116				t.Fatalf("query %q: owning locus fact rank=%d, want 1..%d", scenario.query, rank, scenario.maxRank)
   117			}
   118		}
   119	}
