   121	// Locus values are explicit addresses attached to a fact. BM25 used to omit
   122	// them even though the default hand-rolled lexical arm gives them a strong
   123	// boost, making identifier-only queries silently miss under the BM25 opt-in.
   124	func TestFactsBM25IndexesLocusIdentifiers(t *testing.T) {
