454	// --- identity, not arithmetic ---------------------------------------------
455	//
456	// Everything above this line corrupts the store in a way that changes how MANY
457	// facts it yields. The cases below change WHICH facts it yields and leave the
458	// count alone, which is the shape a count comparison cannot see at all.
459	
460	// overwriteFactLineWithLine replaces the record on line dst with a byte copy of
461	// the record on line src, the way a botched hand edit, a bad merge resolution
462	// or a partially-rewritten block does. The store stays valid NDJSON, every line
463	// still parses, and the line count never moves — only the fact that used to
464	// live on dst is gone. It returns the id that was destroyed and the id that now
465	// stands in its place.
466	func overwriteFactLineWithLine(t *testing.T, path string, src, dst int) (destroyed, standin string) {
467		t.Helper()
468		data, err := os.ReadFile(path)
469		if err != nil {
470			t.Fatal(err)
471		}
472		lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
473		if src < 0 || src >= len(lines) || dst < 0 || dst >= len(lines) || src == dst {
474			t.Fatalf("src=%d dst=%d out of range for a %d-line store", src, dst, len(lines))
475		}
476		idOf := func(n int) string {
477			var record factRecord
478			if err := json.Unmarshal([]byte(lines[n]), &record); err != nil {
479				t.Fatalf("line %d is not a fact to begin with: %v", n, err)
480			}
481			return record.ID
482		}
483		destroyed, standin = idOf(dst), idOf(src)
484		lines[dst] = lines[src]
485		if err := os.WriteFile(path, []byte(strings.Join(lines, "\n")+"\n"), 0o600); err != nil {
486			t.Fatal(err)
487		}
488		return destroyed, standin
489	}
