383		if err != nil {
384			t.Fatalf("status: %v\n%s", err, statusOut)
385		}
386		if !strings.Contains(statusOut, "5 facts") || strings.Contains(statusOut, "declared") {
387			t.Fatalf("intact store changed the status identity line:\n%s", statusOut)
388		}
389	
390		checks, _ := brainDoctorReadOnlyReport(context.Background(), opts, repoDir)
391		if state, _ := factsDoctorCheckState(checks); state != "ok" {
392			t.Fatalf("doctor facts = %q on an intact store, want ok", state)
393		}
394	
395		// The fixture's anchors cite a session this brain does not retain, so
396		// verify legitimately reports orphaned facts here. What must NOT appear is
397		// a store-integrity verdict: the store itself is whole.
398		verifyOut, verifyErr := execute(t, NewRootCommand(opts), "verify", "--branch", "feature")
399		if errors.Is(verifyErr, errVerifyStoreIncomplete) {
400			t.Fatalf("verify reported a store defect on an intact store:\n%s", verifyOut)
401		}
402		if strings.Contains(verifyOut, "store integrity") {
403			t.Fatalf("verify printed a store-integrity line for an intact store:\n%s", verifyOut)
404		}
405		mapOut, err := execute(t, NewRootCommand(opts), "facts", "map", "--branch", "feature")
406		if err != nil {
407			t.Fatalf("facts map failed on an intact store: %v\n%s", err, mapOut)
408		}
409		if strings.Contains(mapOut, "warning:") {
410			t.Fatalf("facts map warned about an intact store:\n%s", mapOut)
411		}
412	
413		// Everything above is silence, and silence is also what a check that never
414		// ran produces. This is the assertion that separates "intact" from
415		// "unmeasured": the cross-check must have counted all five facts.
416		if integrity.Declared != 5 || integrity.Readable != 5 {
417			t.Fatalf("declared/readable = %d/%d, want 5/5", integrity.Declared, integrity.Readable)
418		}
