421	// TestFactStoreIntegrityEmptyBrainReportsNoLoss is the other negative control,
422	// and the one a naive count check gets wrong: a brain that never held a fact
423	// has lost nothing, and must keep saying so in its own words.
424	func TestFactStoreIntegrityEmptyBrainReportsNoLoss(t *testing.T) {
425		now := time.Date(2026, 6, 10, 12, 0, 0, 0, time.UTC)
426		brainDir := writeDistillFixture(t, now)
427	
428		if got := inspectBrainFactStore(brainDir); !got.OK() {
429			t.Fatalf("a brain with no fact source reported loss: %+v", got)
430		}
431	
432		// A declared-but-genuinely-empty fact source is the sharper case: zero
433		// declared and zero readable agree, and nothing is wrong.
434		manifest, err := loadBrainManifest(brainDir)
435		if err != nil {
436			t.Fatal(err)
437		}
438		manifest.Sources.Facts = &factSourceManifest{GeneratedAt: now}
439		if err := writeBrainManifestAndReadme(brainDir, *manifest); err != nil {
440			t.Fatal(err)
441		}
442		got := inspectBrainFactStore(brainDir)
443		if !got.OK() {
444			t.Fatalf("an empty-but-declared fact source reported loss: %+v", got)
445		}
446		if got.Warning() != "" {
447			t.Fatalf("empty brain produced a warning: %q", got.Warning())
448		}
449		if note := emptyResultBlindSpot(brainDir); !strings.Contains(note, "may genuinely not be in the brain") {
450			t.Fatalf("an empty brain must still vouch for its empty result, got %q", note)
451		}
452	}
453	
454	// --- identity, not arithmetic ---------------------------------------------
455	//
456	// Everything above this line corrupts the store in a way that changes how MANY
457	// facts it yields. The cases below change WHICH facts it yields and leave the
458	// count alone, which is the shape a count comparison cannot see at all.
459	
460	// overwriteFactLineWithLine replaces the record on line dst with a byte copy of
461	// the record on line src, the way a botched hand edit, a bad merge resolution
462	// or a partially-rewritten block does. The store stays valid NDJSON, every line
463	// still parses, and the line count never moves — only the fact that used to
464	// live on dst is gone. It returns the id that was destroyed and the id that now
465	// stands in its place.
466	func overwriteFactLineWithLine(t *testing.T, path string, src, dst int) (destroyed, standin string) {
467		t.Helper()
468		data, err := os.ReadFile(path)
469		if err != nil {
470			t.Fatal(err)
471		}
472		lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
473		if src < 0 || src >= len(lines) || dst < 0 || dst >= len(lines) || src == dst {
474			t.Fatalf("src=%d dst=%d out of range for a %d-line store", src, dst, len(lines))
475		}
476		idOf := func(n int) string {
477			var record factRecord
478			if err := json.Unmarshal([]byte(lines[n]), &record); err != nil {
479				t.Fatalf("line %d is not a fact to begin with: %v", n, err)
480			}
481			return record.ID
482		}
483		destroyed, standin = idOf(dst), idOf(src)
484		lines[dst] = lines[src]
485		if err := os.WriteFile(path, []byte(strings.Join(lines, "\n")+"\n"), 0o600); err != nil {
486			t.Fatal(err)
487		}
488		return destroyed, standin
489	}
490	
491	// TestFactStoreIntegrityDetectsCountPreservingOverwrite is the case the count
492	// comparison misses completely: five lines in, five lines out, five declared,
493	// five readable — and one fact replaced by a duplicate of another. `get` says
494	// "not found" for an id the caller is holding, so the loss is real; every
495	// health surface used to say the store was fine.
496	func TestFactStoreIntegrityDetectsCountPreservingOverwrite(t *testing.T) {
497		opts, repoDir, brainDir, path := factLossFixture(t)
498	
499		destroyed, standin := overwriteFactLineWithLine(t, path, 0, 1)
500	
501		t.Run("cross-check", func(t *testing.T) {
502			integrity := inspectBrainFactStore(brainDir)
503			if integrity.OK() {
504				t.Fatalf("integrity reports a healthy store after a fact was overwritten by its neighbour: %+v", integrity)
505			}
506			if integrity.Mode != factStoreDefectDuplicated {
507				t.Fatalf("mode = %q, want %q", integrity.Mode, factStoreDefectDuplicated)
508			}
509			// The counts AGREE. That is the whole point: this defect is invisible
510			// to them, and the check must not depend on them disagreeing.
511			if integrity.Declared != 5 || integrity.Readable != 5 || integrity.Lost() != 0 {
512				t.Fatalf("declared/readable/lost = %d/%d/%d, want 5/5/0: the corruption preserves the count",
513					integrity.Declared, integrity.Readable, integrity.Lost())
514			}
515			if integrity.Distinct != 4 || integrity.Overwritten() != 1 {
516				t.Fatalf("distinct/overwritten = %d/%d, want 4/1", integrity.Distinct, integrity.Overwritten())
517			}
518			if len(integrity.DuplicateIDs) != 1 || integrity.DuplicateIDs[0] != standin {
519				t.Fatalf("duplicate ids = %v, want [%s]", integrity.DuplicateIDs, standin)
520			}
521			if !strings.Contains(integrity.Warning(), standin) {
522				t.Fatalf("warning does not name the colliding id: %q", integrity.Warning())
523			}
524			if !strings.Contains(integrity.Warning(), "entire brain refresh") {
525				t.Fatalf("warning does not name the repair command: %q", integrity.Warning())
526			}
527			// The stale wording is the one thing this must never say: `refresh`
528			// alone would re-declare the collided store and silence the brain.
529			if strings.Contains(integrity.Warning(), "the manifest is behind the store") {
530				t.Fatalf("a substitution was reported as a stale manifest: %q", integrity.Warning())
531			}
532		})
533	
534		// The fact really is gone — without this the rest is a false alarm.
535		t.Run("get", func(t *testing.T) {
536			getOut, err := execute(t, NewRootCommand(opts), "get", destroyed, "--branch", "feature")
537			if err == nil {
538				t.Fatalf("get exited clean for an id it could not produce:\n%s", getOut)
539			}
540			if !strings.Contains(getOut, "not found") {
541				t.Fatalf("the fixture did not actually lose the fact:\n%s", getOut)
542			}
543			if !strings.Contains(getOut, "NOT evidence of absence") {
544				t.Fatalf("get reported \"not found\" for an overwritten fact with no qualification:\n%s", getOut)
545			}
546		})
547	
548		t.Run("status", func(t *testing.T) {
549			report, err := buildAvailableBrainStatusReport(context.Background(), opts, repoDir)
550			if err != nil {
551				t.Fatalf("status report: %v", err)
552			}
553			if report.Facts == nil || report.Facts.Integrity == nil {
554				t.Fatalf("status facts carries no integrity verdict: %+v", report.Facts)
555			}
556			if !warningsMention(report.Warnings, "not unique") {
557				t.Fatalf("status warnings do not name the collision: %v", report.Warnings)
558			}
559		})
560	
561		t.Run("doctor", func(t *testing.T) {
562			checks, _ := brainDoctorReadOnlyReport(context.Background(), opts, repoDir)
563			state, ok := factsDoctorCheckState(checks)
564			if !ok {
565				t.Fatalf("doctor has no facts check: %+v", checks)
566			}
567			if state != "error" {
568				t.Fatalf("doctor facts = %q, want error", state)
569			}
570		})
571	
572		t.Run("verify", func(t *testing.T) {
573			verifyOut, verifyErr := execute(t, NewRootCommand(opts), "verify", "--branch", "feature")
574			if verifyErr == nil {
575				t.Fatalf("verify passed over a store that overwrote a fact:\n%s", verifyOut)
576			}
577			if !strings.Contains(verifyOut, "store integrity") {
578				t.Fatalf("verify did not report the store defect:\n%s", verifyOut)
579			}
580		})
581	
582		t.Run("facts-map", func(t *testing.T) {
583			mapOut, mapErr := execute(t, NewRootCommand(opts), "facts", "map", "--branch", "feature")
584			if mapErr == nil {
585				t.Fatalf("facts map exited clean over a collided store:\n%s", mapOut)
586			}
587			if !strings.Contains(mapOut, "not unique") {
588				t.Fatalf("facts map did not qualify its counts:\n%s", mapOut)
589			}
590		})
591	
592		t.Run("facts-tree", func(t *testing.T) {
593			treeOut, treeErr := execute(t, NewRootCommand(opts), "facts", "tree", "--branch", "feature")
594			if treeErr == nil {
595				t.Fatalf("facts tree exited clean over a collided store:\n%s", treeOut)
596			}
597			if !strings.Contains(treeOut, "not unique") {
598				t.Fatalf("facts tree did not qualify its hierarchy:\n%s", treeOut)
599			}
600		})
601	
602		t.Run("facts-status", func(t *testing.T) {
603			statusOut, err := execute(t, NewRootCommand(opts), "facts", "status", "--branch", "feature")
604			if err != nil && !strings.Contains(statusOut, "not unique") {
605				t.Fatalf("facts status: %v\n%s", err, statusOut)
606			}
607			if !strings.Contains(statusOut, "not unique") {
608				t.Fatalf("facts status reported totals without naming the collision:\n%s", statusOut)
609			}
610		})
611	
612		// The retrieval note is the surface #242 exists for. An empty result over
613		// a store with a hole in it must not be explained away.
614		t.Run("retrieval-note", func(t *testing.T) {
615			note := emptyResultBlindSpot(brainDir)
616			if strings.Contains(note, "may genuinely not be in the brain") {
617				t.Fatalf("the note still vouches for the empty over a collided store: %q", note)
618			}
619			if !strings.Contains(note, "NOT evidence of absence") {
620				t.Fatalf("the note does not correct the empty result: %q", note)
621			}
622		})
623	
624		t.Run("search", func(t *testing.T) {
625			searchOut, err := execute(t, NewRootCommand(opts), "search", "zzqqxxwwvv")
626			if err != nil {
627				t.Fatalf("search: %v\n%s", err, searchOut)
628			}
629			if strings.Contains(searchOut, "may genuinely not be in the brain") {
630				t.Fatalf("search still explains the empty away:\n%s", searchOut)
631			}
632			if !strings.Contains(searchOut, "NOT evidence of absence") {
633				t.Fatalf("search did not warn that the store overwrote a fact:\n%s", searchOut)
634			}
635		})
636	
637		t.Run("recall", func(t *testing.T) {
638			recallOut, err := execute(t, NewRootCommand(opts), "recall", "alpha", "--branch", "feature")
639			if err != nil && !strings.Contains(recallOut, "not unique") {
640				t.Fatalf("recall: %v\n%s", err, recallOut)
641			}
642			if !strings.Contains(recallOut, "not unique") {
643				t.Fatalf("recall served facts from a collided store without a warning:\n%s", recallOut)
644			}
645		})
646	
647		t.Run("query", func(t *testing.T) {
648			queryOut, err := execute(t, NewRootCommand(opts), "query", "zzqqxxwwvv")
649			if err != nil {
650				t.Fatalf("query: %v\n%s", err, queryOut)
651			}
652			if strings.Contains(queryOut, "may genuinely not be in the brain") {
653				t.Fatalf("query still explains the empty away:\n%s", queryOut)
654			}
655		})
656	}
657	
658	// TestFactStoreIntegrityAppendedDuplicateIsNotAStaleManifest pins the OTHER
659	// duplicate shape and why it needed its own mode rather than the one it used to
660	// land in.
661	//
662	// Appending a copy of an existing line also makes the store longer than the
663	// manifest, so the count comparison already caught it — as "stale", whose
664	// advice is "the manifest is behind the store — run `entire brain refresh`".
665	// That advice is actively harmful here: refresh re-derives the count from the
666	// collided store, declares 6, and every surface goes quiet about a fact set
667	// that holds one id twice. Nothing was ever noticing the DUPLICATE; it was
668	// noticing a number that went up.
669	func TestFactStoreIntegrityAppendedDuplicateIsNotAStaleManifest(t *testing.T) {
670		_, _, brainDir, path := factLossFixture(t)
671	
672		data, err := os.ReadFile(path)
673		if err != nil {
674			t.Fatal(err)
675		}
676		lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
677		if err := os.WriteFile(path, []byte(strings.Join(append(lines, lines[0]), "\n")+"\n"), 0o600); err != nil {
678			t.Fatal(err)
679		}
680	
681		got := inspectBrainFactStore(brainDir)
682		if got.Mode != factStoreDefectDuplicated {
683			t.Fatalf("mode = %q, want %q: a repeated id is a collision, not a manifest that fell behind", got.Mode, factStoreDefectDuplicated)
684		}
685		if got.Readable != 6 || got.Distinct != 5 || got.Overwritten() != 1 {
686			t.Fatalf("readable/distinct/overwritten = %d/%d/%d, want 6/5/1", got.Readable, got.Distinct, got.Overwritten())
687		}
688		if strings.Contains(got.Warning(), "the manifest is behind the store") {
689			t.Fatalf("a colliding store was still told to just refresh: %q", got.Warning())
690		}
691		if !strings.Contains(got.Warning(), factsRepairHint) {
692			t.Fatalf("warning does not name the repair: %q", got.Warning())
693		}
694	}
695	
696	// TestFactStoreIntegrityStaleStaysStale is the control for the reclassification
697	// above: a store that genuinely holds MORE distinct facts than the manifest
698	// declares is still a manifest that fell behind, and must keep its own words
699	// and its own repair (refresh, no re-distill).
700	func TestFactStoreIntegrityStaleStaysStale(t *testing.T) {
701		_, _, brainDir, path := factLossFixture(t)
702	
703		extra := factRecord{
704			ID:         factRecordID("a sixth fact nobody told the manifest about", []string{"project.tooling.stack"}),
705			Paths:      []string{"project.tooling.stack"},
706			Text:       "a sixth fact nobody told the manifest about",
707			Branch:     "feature",
708			Origin:     factOriginAuthored,
709			Status:     factStatusActive,
710			Provenance: []factAnchor{{SessionID: "session-1"}},
711		}
712		encoded, err := json.Marshal(extra)
713		if err != nil {
714			t.Fatal(err)
715		}
716		f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY, 0o600)
717		if err != nil {
718			t.Fatal(err)
719		}
720		if _, err := f.Write(append(encoded, '\n')); err != nil {
721			t.Fatal(err)
722		}
723		if err := f.Close(); err != nil {
724			t.Fatal(err)
725		}
726	
727		got := inspectBrainFactStore(brainDir)
728		if got.Mode != factStoreDefectStale {
729			t.Fatalf("mode = %q, want stale", got.Mode)
730		}
731		if got.Distinct != 6 || got.Overwritten() != 0 {
732			t.Fatalf("distinct/overwritten = %d/%d, want 6/0", got.Distinct, got.Overwritten())
733		}
734		if !strings.Contains(got.Warning(), "the manifest is behind the store") {
735			t.Fatalf("stale lost its own words: %q", got.Warning())
736		}
737	}
738	
739	// TestFactStoreIntegrityShortAndCollidedReportsBoth covers a store that is both
740	// short AND collided. "lossy" stays the mode — a shortfall is the more urgent
741	// framing and keeps its wording — but the line must not stop at the arithmetic:
742	// the overwritten fact is gone too, and it is not one of the ones the count
743	// accounted for.
744	func TestFactStoreIntegrityShortAndCollidedReportsBoth(t *testing.T) {
745		_, _, brainDir, path := factLossFixture(t)
746	
747		overwriteFactLineWithLine(t, path, 0, 1)
748		replaceFactLines(t, path, `{"hello":"world"}`, 4)
749	
750		got := inspectBrainFactStore(brainDir)
751		if got.Mode != factStoreDefectLossy {
752			t.Fatalf("mode = %q, want lossy: a short store is still short", got.Mode)
753		}
754		if !strings.Contains(got.Warning(), "5 declared, 4 readable") {
755			t.Fatalf("lossy lost its own words: %q", got.Warning())
756		}
757		if !strings.Contains(got.Warning(), "repeat a fact id") {
758			t.Fatalf("a store that is short AND collided reported only the shortfall: %q", got.Warning())
759		}
760	}
761	
762	// TestFactStoreIntegrityAllowsOneIDOnTwoBranches is the false-positive control
763	// the id comparison exists under, and the reason it is scoped to a branch.
764	//
765	// A fact id is sha256(normalized text + sorted paths) — the branch is not in it
766	// — so the same fact on two branches is the same id by design, and `facts
767	// promote` produces exactly that on purpose. A brain-wide id set would call
768	// every promote data loss.
769	func TestFactStoreIntegrityAllowsOneIDOnTwoBranches(t *testing.T) {
770		_, _, brainDir, _ := factLossFixture(t)
771		now := time.Date(2026, 8, 10, 3, 0, 0, 0, time.UTC)
772	
773		feature, err := loadFacts(brainDir, "feature")
774		if err != nil {
775			t.Fatal(err)
776		}
777		carried := make([]factRecord, 0, len(feature))
778		for _, fact := range feature {
779			fact.Branch = "main"
780			carried = append(carried, fact)
781		}
782		if err := writeFacts(brainDir, "main", carried); err != nil {
783			t.Fatal(err)
784		}
785		if err := updateFactSourceManifest(brainDir, now); err != nil {
786			t.Fatal(err)
787		}
788	
789		got := inspectBrainFactStore(brainDir)
790		if !got.OK() {
791			t.Fatalf("carrying a branch's facts into another branch was reported as corruption: %+v\n%s", got, got.Warning())
792		}
793		if got.Readable != 10 || got.Distinct != 10 {
794			t.Fatalf("readable/distinct = %d/%d, want 10/10: ids repeat ACROSS branches, never within one", got.Readable, got.Distinct)
795		}
796	}
797	
798	// TestFactStoreIntegrityHealthyStoreHasNoCollisions extends the healthy-brain
799	// control to identity: silence is also what an unrun check produces, so assert
800	// the checker actually resolved five distinct ids.
801	func TestFactStoreIntegrityHealthyStoreHasNoCollisions(t *testing.T) {
802		_, _, brainDir, _ := factLossFixture(t)
803	
804		got := inspectBrainFactStore(brainDir)
805		if !got.OK() {
806			t.Fatalf("an intact five-fact store failed the identity check: %+v", got)
807		}
808		if got.Distinct != 5 || got.Overwritten() != 0 || len(got.DuplicateIDs) != 0 {
809			t.Fatalf("distinct/overwritten/duplicates = %d/%d/%v, want 5/0/[]", got.Distinct, got.Overwritten(), got.DuplicateIDs)
810		}
811	}

