491	// TestFactStoreIntegrityDetectsCountPreservingOverwrite is the case the count
492	// comparison misses completely: five lines in, five lines out, five declared,
493	// five readable — and one fact replaced by a duplicate of another. `get` says
494	// "not found" for an id the caller is holding, so the loss is real; every
495	// health surface used to say the store was fine.
496	func TestFactStoreIntegrityDetectsCountPreservingOverwrite(t *testing.T) {
497		opts, repoDir, brainDir, path := factLossFixture(t)
498	
499		destroyed, standin := overwriteFactLineWithLine(t, path, 0, 1)
500	
501		t.Run("cross-check", func(t *testing.T) {
502			integrity := inspectBrainFactStore(brainDir)
503			if integrity.OK() {
504				t.Fatalf("integrity reports a healthy store after a fact was overwritten by its neighbour: %+v", integrity)
505			}
506			if integrity.Mode != factStoreDefectDuplicated {
507				t.Fatalf("mode = %q, want %q", integrity.Mode, factStoreDefectDuplicated)
508			}
509			// The counts AGREE. That is the whole point: this defect is invisible
510			// to them, and the check must not depend on them disagreeing.
511			if integrity.Declared != 5 || integrity.Readable != 5 || integrity.Lost() != 0 {
512				t.Fatalf("declared/readable/lost = %d/%d/%d, want 5/5/0: the corruption preserves the count",
513					integrity.Declared, integrity.Readable, integrity.Lost())
514			}
515			if integrity.Distinct != 4 || integrity.Overwritten() != 1 {
516				t.Fatalf("distinct/overwritten = %d/%d, want 4/1", integrity.Distinct, integrity.Overwritten())
517			}
518			if len(integrity.DuplicateIDs) != 1 || integrity.DuplicateIDs[0] != standin {
519				t.Fatalf("duplicate ids = %v, want [%s]", integrity.DuplicateIDs, standin)
520			}
521			if !strings.Contains(integrity.Warning(), standin) {
522				t.Fatalf("warning does not name the colliding id: %q", integrity.Warning())
523			}
524			if !strings.Contains(integrity.Warning(), "entire brain refresh") {
525				t.Fatalf("warning does not name the repair command: %q", integrity.Warning())
526			}
527			// The stale wording is the one thing this must never say: `refresh`
528			// alone would re-declare the collided store and silence the brain.
529			if strings.Contains(integrity.Warning(), "the manifest is behind the store") {
530				t.Fatalf("a substitution was reported as a stale manifest: %q", integrity.Warning())
531			}
532		})
533	
534		// The fact really is gone — without this the rest is a false alarm.
535		t.Run("get", func(t *testing.T) {
536			getOut, err := execute(t, NewRootCommand(opts), "get", destroyed, "--branch", "feature")
537			if err == nil {
538				t.Fatalf("get exited clean for an id it could not produce:\n%s", getOut)
539			}
540			if !strings.Contains(getOut, "not found") {
541				t.Fatalf("the fixture did not actually lose the fact:\n%s", getOut)
542			}
543			if !strings.Contains(getOut, "NOT evidence of absence") {
544				t.Fatalf("get reported \"not found\" for an overwritten fact with no qualification:\n%s", getOut)
545			}
546		})
547	
548		t.Run("status", func(t *testing.T) {
549			report, err := buildAvailableBrainStatusReport(context.Background(), opts, repoDir)
550			if err != nil {
551				t.Fatalf("status report: %v", err)
552			}
553			if report.Facts == nil || report.Facts.Integrity == nil {
554				t.Fatalf("status facts carries no integrity verdict: %+v", report.Facts)
