743	// accounted for.
744	func TestFactStoreIntegrityShortAndCollidedReportsBoth(t *testing.T) {
745		_, _, brainDir, path := factLossFixture(t)
746	
747		overwriteFactLineWithLine(t, path, 0, 1)
748		replaceFactLines(t, path, `{"hello":"world"}`, 4)
749	
750		got := inspectBrainFactStore(brainDir)
751		if got.Mode != factStoreDefectLossy {
752			t.Fatalf("mode = %q, want lossy: a short store is still short", got.Mode)
753		}
754		if !strings.Contains(got.Warning(), "5 declared, 4 readable") {
755			t.Fatalf("lossy lost its own words: %q", got.Warning())
756		}
757		if !strings.Contains(got.Warning(), "repeat a fact id") {
758			t.Fatalf("a store that is short AND collided reported only the shortfall: %q", got.Warning())
759		}
