762	// TestFactStoreIntegrityAllowsOneIDOnTwoBranches is the false-positive control
763	// the id comparison exists under, and the reason it is scoped to a branch.
764	//
765	// A fact id is sha256(normalized text + sorted paths) — the branch is not in it
766	// — so the same fact on two branches is the same id by design, and `facts
767	// promote` produces exactly that on purpose. A brain-wide id set would call
768	// every promote data loss.
769	func TestFactStoreIntegrityAllowsOneIDOnTwoBranches(t *testing.T) {
770		_, _, brainDir, _ := factLossFixture(t)
771		now := time.Date(2026, 8, 10, 3, 0, 0, 0, time.UTC)
772	
773		feature, err := loadFacts(brainDir, "feature")
774		if err != nil {
775			t.Fatal(err)
776		}
777		carried := make([]factRecord, 0, len(feature))
778		for _, fact := range feature {
779			fact.Branch = "main"
780			carried = append(carried, fact)
781		}
782		if err := writeFacts(brainDir, "main", carried); err != nil {
783			t.Fatal(err)
784		}
785		if err := updateFactSourceManifest(brainDir, now); err != nil {
786			t.Fatal(err)
787		}
788	
789		got := inspectBrainFactStore(brainDir)
790		if !got.OK() {
791			t.Fatalf("carrying a branch's facts into another branch was reported as corruption: %+v\n%s", got, got.Warning())
792		}
793		if got.Readable != 10 || got.Distinct != 10 {
794			t.Fatalf("readable/distinct = %d/%d, want 10/10: ids repeat ACROSS branches, never within one", got.Readable, got.Distinct)
795		}
796	}
