798	// TestFactStoreIntegrityHealthyStoreHasNoCollisions extends the healthy-brain
799	// control to identity: silence is also what an unrun check produces, so assert
800	// the checker actually resolved five distinct ids.
801	func TestFactStoreIntegrityHealthyStoreHasNoCollisions(t *testing.T) {
802		_, _, brainDir, _ := factLossFixture(t)
