     8	
     9	// distill's private review backlog and a cross-member conflict raised by
    10	// `facts sync` can name the same action/candidate/target — the shared head holds
    11	// this member's own facts, so the pair repeats. They are DIFFERENT rows to every
    12	// layer that keys on factsync.ProposalID (branch and proposed_by included), so
    13	// the queue must keep both.
    14	func TestDedupeProposalsKeepsMemberAttribution(t *testing.T) {
    15		private := factProposal{Action: factActionSupersede, CandidateID: "fact:c", TargetID: "fact:t"}
    16		shared := factProposal{Action: factActionSupersede, CandidateID: "fact:c", TargetID: "fact:t", Branch: "main", ProposedBy: "alice@example.com"}
    17	
    18		got := dedupeProposals([]factProposal{private, shared})
    19		if len(got) != 2 {
    20			t.Fatalf("want both the private and the member-attributed proposal, got %+v", got)
    21		}
    22		if factsync.ProposalID(got[0]) == factsync.ProposalID(got[1]) {
    23			t.Fatalf("dedupe kept two entries with the same shared-queue id: %+v", got)
    24		}
    25		// A true duplicate still collapses.
    26		if again := dedupeProposals([]factProposal{shared, shared, private}); len(again) != 2 {
    27			t.Fatalf("identical entries must still collapse: %+v", again)
    28		}
    29		// Deterministic order regardless of input order.
    30		a := dedupeProposals([]factProposal{private, shared})
    31		b := dedupeProposals([]factProposal{shared, private})
    32		for i := range a {
    33			if factsync.ProposalID(a[i]) != factsync.ProposalID(b[i]) {
    34				t.Fatalf("dedupe order depends on input order: %+v vs %+v", a, b)
    35			}
    36		}
    37	}
    38	
    39	// End to end through the durable queue: a sync that raises a conflict already
    40	// present in distill's private backlog must still leave a publishable,
    41	// member-attributed entry on disk. Without it, `facts sync` skips the entry
    42	// (it publishes only attributed ones) and the team never sees the conflict.
    43	func TestPersistFactsSyncProposalsKeepsAttributedEntry(t *testing.T) {
    44		brainDir, branch := t.TempDir(), "main"
    45		private := factProposal{Action: factActionSupersede, CandidateID: "fact:c", TargetID: "fact:t"}
    46		if err := writeFactProposals(brainDir, branch, []factProposal{private}); err != nil {
    47			t.Fatal(err)
    48		}
    49		raised := factProposal{Action: factActionSupersede, CandidateID: "fact:c", TargetID: "fact:t", Branch: branch, ProposedBy: "alice@example.com", Confidence: 0}
    50		if err := persistFactsSyncProposals(brainDir, branch, []factProposal{raised}); err != nil {
    51			t.Fatal(err)
    52		}
    53		queue, err := loadFactProposals(brainDir, branch)
    54		if err != nil {
    55			t.Fatal(err)
    56		}
    57		publishable := 0
    58		for _, p := range queue {
    59			if p.ProposedBy != "" {
    60				publishable++
    61			}
    62		}
    63		if publishable != 1 {
    64			t.Fatalf("the cross-member conflict is not publishable after persisting; queue = %+v", queue)
    65		}
    66	}

