    57	func (f *hostedProposalsFake) handler() http.Handler {
    58		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    59			f.mu.Lock()
    60			f.requests++
    61			f.mu.Unlock()
    62			w.Header().Set("Content-Type", "application/json")
    63			path := r.URL.Path
    64	
    65			switch {
    66			case strings.HasSuffix(path, "/brain/facts/proposals") && r.Method == http.MethodGet:
    67				if f.failList != 0 {
    68					w.WriteHeader(f.failList)
    69					return
    70				}
    71				f.mu.Lock()
    72				defer f.mu.Unlock()
    73				_ = json.NewEncoder(w).Encode(map[string]any{"found": len(f.proposals) > 0, "ref": "props-1", "proposals": f.proposals})
    74	
    75			case strings.HasSuffix(path, "/brain/facts/proposals") && r.Method == http.MethodPost:
    76				if f.failPublish != 0 {
    77					w.WriteHeader(f.failPublish)
    78					return
    79				}
    80				var body struct {
    81					Proposals []factsync.OpenProposal `json:"proposals"`
    82				}
    83				if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
    84					w.WriteHeader(http.StatusBadRequest)
    85					return
    86				}
    87				f.mu.Lock()
    88				defer f.mu.Unlock()
    89				f.proposals = body.Proposals
    90				_ = json.NewEncoder(w).Encode(map[string]any{"ref": "props-2", "changed": true})
    91	
    92			case strings.HasSuffix(path, "/brain/facts/advance") && r.Method == http.MethodPost:
    93				var body struct {
    94					Data []byte `json:"data"`
    95				}
    96				if err := json.NewDecoder(r.Body).Decode(&body); err != nil || len(body.Data) == 0 {
    97					w.WriteHeader(http.StatusBadRequest)
    98					return
    99				}
   100				f.mu.Lock()
   101				defer f.mu.Unlock()
   102				f.facts = body.Data
   103				_ = json.NewEncoder(w).Encode(map[string]any{"newRef": "facts-2", "changed": true})
   104	
   105			case strings.HasSuffix(path, "/resolve") && r.Method == http.MethodPost:
   106				var body struct {
   107					Data      []byte                  `json:"data"`
   108					Proposals []factsync.OpenProposal `json:"proposals"`
   109				}
   110				if err := json.NewDecoder(r.Body).Decode(&body); err != nil || len(body.Data) == 0 {
   111					w.WriteHeader(http.StatusBadRequest)
   112					return
   113				}
   114				f.mu.Lock()
   115				defer f.mu.Unlock()
   116				f.facts, f.proposals = body.Data, body.Proposals
   117				_ = json.NewEncoder(w).Encode(map[string]any{"factsRef": "facts-2", "proposalsRef": "props-2", "changed": true})
   118	
   119			case strings.Contains(path, "/brain/facts/proposals/") && r.Method == http.MethodGet:
   120				id := path[strings.LastIndex(path, "/")+1:]
   121				f.mu.Lock()
   122				defer f.mu.Unlock()
   123				for _, p := range f.proposals {
   124					if p.ID == id {
   125						_ = json.NewEncoder(w).Encode(map[string]any{"found": true, "ref": "props-1", "proposal": p})
   126						return
   127					}
   128				}
   129				w.WriteHeader(http.StatusNotFound)
   130	
   131			case strings.HasSuffix(path, "/brain/facts") && r.Method == http.MethodGet:
   132				f.mu.Lock()
   133				defer f.mu.Unlock()
   134				_ = json.NewEncoder(w).Encode(map[string]any{"found": len(f.facts) > 0, "ref": "facts-1", "data": f.facts})
   135	
   136			default:
   137				w.WriteHeader(http.StatusNotFound)
   138			}
   139		})
   140	}
