   183	// TestFactsProposalsRefusesWithoutGates is the no-implicit-egress table: every
   184	// unsatisfied gate and every missing target field refuses BEFORE any HTTP request.
   185	func TestFactsProposalsRefusesWithoutGates(t *testing.T) {
   186		for _, tc := range []struct {
   187			name string
   188			env  map[string]string
   189			args []string
   190			want string
   191		}{
   192			{name: "opt-in unset", env: map[string]string{"ENTIRE_BRAIN_ALLOW_HOSTED": ""}, want: "hosted_proposals_disabled"},
   193			{name: "opt-in false", env: map[string]string{"ENTIRE_BRAIN_ALLOW_HOSTED": "false"}, want: "hosted_proposals_disabled"},
   194			{name: "no-egress wins", env: map[string]string{"ENTIRE_BRAIN_NO_EGRESS": "1"}, want: "no_egress"},
   195			{name: "local-only wins", env: map[string]string{"ENTIRE_BRAIN_LOCAL_ONLY": "1"}, want: "no_egress"},
   196			{name: "missing repo id", env: map[string]string{"ENTIRE_REPO_ID": ""}, want: "target repo id is required"},
   197			{name: "missing api url", env: map[string]string{"ENTIRE_API_URL": ""}, want: "API base URL is required"},
   198			{name: "missing token", env: map[string]string{"ENTIRE_API_TOKEN": ""}, want: "API token is required"},
   199		} {
   200			t.Run(tc.name, func(t *testing.T) {
   201				f, fake, proposal := newHostedProposalsFixture(t)
   202				for k, v := range tc.env {
   203					t.Setenv(k, v)
   204				}
   205				for _, args := range [][]string{
   206					{"facts", "proposals", "list"},
   207					{"facts", "proposals", "repair"},
   208					{"facts", "proposals", "repair", "--apply", "--if-ref", "reviewed-ref"},
   209					{"facts", "proposals", "show", proposal.ID},
   210					{"facts", "proposals", "apply", proposal.ID},
   211					{"facts", "proposals", "reject", proposal.ID},
   212				} {
   213					out, err := execute(t, NewRootCommand(f.opts), args...)
   214					if err == nil {
   215						t.Fatalf("%v succeeded despite %s\n%s", args, tc.name, out)
   216					}
   217					if !strings.Contains(err.Error(), tc.want) {
   218						t.Fatalf("%v error = %v; want %q", args, err, tc.want)
   219					}
   220				}
   221				if n := fake.count(); n != 0 {
   222					t.Fatalf("refused commands still made %d HTTP request(s)", n)
   223				}
   224				// The open set is untouched: nothing was resolved.
   225				if len(fake.openSet()) != 1 {
   226					t.Fatalf("open set changed under a refusal: %+v", fake.openSet())
   227				}
   228			})
   229		}
   230	}
