   332	// TestFactsProposalsApplyConverges drives the whole user-facing loop against the fake
   333	// hosted brain: list → apply → the shared head converges (loser retained as
   334	// superseded, winner active) and the queue empties.
   335	func TestFactsProposalsApplyConverges(t *testing.T) {
   336		f, fake, proposal := newHostedProposalsFixture(t)
   337	
   338		out, err := execute(t, NewRootCommand(f.opts), "facts", "proposals", "apply", proposal.ID)
   339		if err != nil {
   340			t.Fatalf("facts proposals apply: %v\n%s", err, out)
   341		}
   342		for _, want := range []string{"applied " + proposal.ID, "facts head: facts-2", "0 open proposal(s) remain"} {
   343			if !strings.Contains(out, want) {
   344				t.Fatalf("apply output missing %q:\n%s", want, out)
   345			}
   346		}
   347		if len(fake.openSet()) != 0 {
   348			t.Fatalf("open set after apply = %+v; want empty", fake.openSet())
   349		}
   350	
   351		byID := map[string]factRecord{}
   352		for _, r := range fake.headFacts(t) {
   353			byID[r.ID] = r
   354		}
   355		loser := byID[proposal.Proposal.TargetID]
   356		if loser.Status != factStatusSuperseded || loser.SupersededBy != proposal.Proposal.CandidateID {
   357			t.Fatalf("target = %q superseded_by %q; want superseded by the candidate", loser.Status, loser.SupersededBy)
   358		}
   359		if byID[proposal.Proposal.CandidateID].Status != factStatusActive {
   360			t.Fatalf("candidate = %q; want active", byID[proposal.Proposal.CandidateID].Status)
   361		}
   362	
   363		// The settled proposal is gone for everyone; re-applying reports it as such.
   364		out, err = execute(t, NewRootCommand(f.opts), "facts", "proposals", "apply", proposal.ID)
   365		if err == nil {
   366			t.Fatalf("re-applying a settled proposal succeeded:\n%s", out)
   367		}
   368		if !strings.Contains(err.Error(), "no such open proposal") {
   369			t.Fatalf("re-apply error = %v", err)
   370		}
   371	}
