    16	
    17	// envHoldBrainWriteLock names the brain directory the helper process below
    18	// locks. It is only ever set by TestFactsReclassifyWaitsForOtherProcess.
    19	const envHoldBrainWriteLock = "BRAIN_TEST_HOLD_BRAIN_WRITE_LOCK"
    20	
    21	// TestHelperHoldBrainWriteLock is not a test: it is the CHILD process the
    22	// cross-process lock test re-execs. It takes the brain write lock, announces
    23	// that on stdout, holds it until its parent writes a line to stdin, and exits.
    24	// The brain lock is an flock(2) advisory lock, so only a real second process
    25	// proves the contract an in-process mutex would fake.
    26	func TestHelperHoldBrainWriteLock(t *testing.T) {
    27		brainDir := os.Getenv(envHoldBrainWriteLock)
    28		if brainDir == "" {
    29			t.Skip("helper process for TestFactsReclassifyWaitsForOtherProcess")
    30		}
    31		unlock, err := acquireBrainWriteLockTimeout(brainDir, 60*time.Second)
    32		if err != nil {
    33			fmt.Fprintf(os.Stderr, "helper: acquire brain write lock: %v\n", err)
    34			os.Exit(1)
    35		}
    36		fmt.Println("HELPER-LOCKED")
    37		_, _ = bufio.NewReader(os.Stdin).ReadString('\n')
    38		unlock()
    39	}
    40	
    41	// seedReclassifyBrain writes one kind-less fact plus a manifest and returns the
    42	// brain dir and branch.
    43	func seedReclassifyBrain(t *testing.T, now time.Time) (string, string) {
    44		t.Helper()
    45		brainDir, branch := t.TempDir(), "main"
    46		seed := []factRecord{{
    47			ID: "fact:inv", Paths: []string{"constraints.api.shape"},
    48			Text: "The token must never be logged.", Branch: branch,
    49			Origin: factOriginDistilled, Status: factStatusActive,
    50			Provenance: []factAnchor{{SessionID: "s1"}}, UpdatedAt: now,
    51		}}
    52		if err := writeFacts(brainDir, branch, seed); err != nil {
    53			t.Fatal(err)
    54		}
    55		if err := writeBrainManifestAndReadme(brainDir, exportManifest{SchemaVersion: brainManifestSchemaVersion, GeneratedAt: now}); err != nil {
    56			t.Fatal(err)
    57		}
    58		return brainDir, branch
    59	}
    60	
    61	func reclassifyTestCommand() (*cobra.Command, *bytes.Buffer) {
    62		cmd := &cobra.Command{}
    63		out := &bytes.Buffer{}
    64		cmd.SetOut(out)
    65		cmd.SetErr(&bytes.Buffer{})
    66		return cmd, out
    67	}
    68	
    69	// TestFactsReclassifyWaitsForOtherProcess proves `facts reclassify` performs its
    70	// load-mutate-write of facts.ndjson under the brain write lock. A second PROCESS
    71	// holds the lock; while it does, reclassify must not have rewritten the store.
    72	// Without the lock it rewrites it immediately and any transaction the other
    73	// process is in the middle of is clobbered.
    74	func TestFactsReclassifyWaitsForOtherProcess(t *testing.T) {
    75		now := time.Date(2026, 6, 16, 12, 0, 0, 0, time.UTC)
    76		brainDir, branch := seedReclassifyBrain(t, now)
    77	
    78		helper := exec.Command(os.Args[0], "-test.run=^TestHelperHoldBrainWriteLock$", "-test.timeout=120s")
    79		helper.Env = append(os.Environ(), envHoldBrainWriteLock+"="+brainDir)
    80		stdin, err := helper.StdinPipe()
    81		if err != nil {
    82			t.Fatal(err)
    83		}
    84		stdout, err := helper.StdoutPipe()
    85		if err != nil {
    86			t.Fatal(err)
    87		}
    88		helper.Stderr = os.Stderr
    89		if err := helper.Start(); err != nil {
    90			t.Skipf("cannot re-exec the test binary as a lock holder: %v", err)
    91		}
    92		defer func() {
    93			_ = stdin.Close()
    94			_ = helper.Wait()
    95		}()
    96	
    97		scanner := bufio.NewScanner(stdout)
    98		locked := false
    99		for scanner.Scan() {
   100			if strings.Contains(scanner.Text(), "HELPER-LOCKED") {
   101				locked = true
   102				break
   103			}
   104		}
   105		if !locked {
   106			t.Fatal("helper process never reported holding the brain write lock")
   107		}
   108	
   109		cmd, _ := reclassifyTestCommand()
   110		opts := Options{Version: "test", Now: func() time.Time { return now }}
   111		done := make(chan error, 1)
   112		go func() { done <- runFactsReclassify(cmd, opts, brainDir, branch, false, false) }()
   113	
   114		time.Sleep(500 * time.Millisecond)
   115		midFlight, err := loadFacts(brainDir, branch)
   116		if err != nil {
   117			t.Fatal(err)
   118		}
   119		if len(midFlight) != 1 || midFlight[0].Kind != "" {
   120			t.Fatalf("facts reclassify rewrote facts.ndjson while another process held the brain write lock: %+v", midFlight)
   121		}
   122	
   123		if _, err := io.WriteString(stdin, "go\n"); err != nil {
   124			t.Fatal(err)
   125		}
   126		if err := <-done; err != nil {
   127			t.Fatalf("reclassify after the lock was released: %v", err)
   128		}
   129		after, err := loadFacts(brainDir, branch)
   130		if err != nil {
   131			t.Fatal(err)
   132		}
   133		if len(after) != 1 || after[0].Kind != factKindInvariant {
   134			t.Fatalf("reclassify did not persist the kind once it held the lock: %+v", after)
   135		}
   136	}
