    43		opts, brainDir, branch := rememberReviveEnv(t, now)
    44	
    45		text := "The user prefers table-driven tests."
    46		paths := normalizeFactPaths([]string{"preferences.coding.style"})
    47		id := factRecordID(text, paths)
    48		seed := []factRecord{{
    49			ID: id, Paths: paths, Kind: factKindPreference, Text: text, Branch: branch,
    50			Origin: factOriginAuthored, Status: factStatusRetracted,
    51			Provenance: []factAnchor{{SessionID: "s1"}},
