    37	// A fact id is content-derived, so re-authoring a statement that was retracted
    38	// lands on the retired record. The author asserted it is true again, so the
    39	// record must go back to active — otherwise `remember` reports success while the
    40	// fact stays unrecallable and the write is silently lost.
    41	func TestRememberRevivesRetractedFact(t *testing.T) {
    42		now := time.Date(2026, 6, 16, 12, 0, 0, 0, time.UTC)
    43		opts, brainDir, branch := rememberReviveEnv(t, now)
    44	
    45		text := "The user prefers table-driven tests."
    46		paths := normalizeFactPaths([]string{"preferences.coding.style"})
    47		id := factRecordID(text, paths)
    48		seed := []factRecord{{
    49			ID: id, Paths: paths, Kind: factKindPreference, Text: text, Branch: branch,
    50			Origin: factOriginAuthored, Status: factStatusRetracted,
    51			Provenance: []factAnchor{{SessionID: "s1"}},
    52			CreatedAt:  now.Add(-time.Hour), UpdatedAt: now.Add(-time.Hour),
    53		}}
    54		if err := writeFacts(brainDir, branch, seed); err != nil {
    55			t.Fatal(err)
    56		}
    57	
    58		printed := runRememberForTest(t, opts, text)
    59	
    60		got, err := loadFacts(brainDir, branch)
    61		if err != nil {
    62			t.Fatal(err)
    63		}
    64		if len(got) != 1 {
    65			t.Fatalf("want 1 fact, got %d: %+v", len(got), got)
    66		}
    67		if got[0].Status != factStatusActive {
    68			t.Fatalf("re-authored fact is still %q after %q: the command reported success but the fact is not recallable", got[0].Status, printed)
    69		}
    70		if !got[0].UpdatedAt.Equal(now) {
    71			t.Errorf("updated_at = %s, want the authoring time %s", got[0].UpdatedAt, now)
    72		}
    73		// Reviving must not discard the retired record's history.
    74		if got[0].CreatedAt.Equal(now) {
    75			t.Errorf("created_at was reset; the original record should be revived, not replaced")
    76		}
    77	}
