    22	// TestReconcileLocalQueuePullsSettlementIntoLocalFacts is the regression for the
    23	// "accepted settlements don't stick" defect. A teammate settling a conflict on the
    24	// hosted queue used to leave the LOSING member's local facts untouched, so the
    25	// next keep-both Promote re-added the retired fact and re-raised the same conflict
    26	// under a fresh id — a loop that member could never clear.
    27	//
    28	// Driven through reconcileLocalProposalQueue directly: the natural sync fixture
    29	// makes the local member WIN its own proposal, so it cannot exercise the losing
    30	// side at all (a test asserting on it passes with the fix reverted).
    31	func TestReconcileLocalQueuePullsSettlementIntoLocalFacts(t *testing.T) {
    32		paths := normalizeFactPaths([]string{"ops.deploy.strategy"})
    33		mk := func(text string) factRecord {
    34			return factRecord{
    35				ID: factRecordID(text, paths), Paths: paths, Text: text, Branch: "main",
    36				Origin: factOriginDistilled, Status: factStatusActive,
    37			}
    38		}
    39		mine, theirs := mk("deploys use a canary rollout"), mk("deploys use blue-green cutover")
    40	
    41		for _, tc := range []struct {
    42			name       string
    43			action     string
    44			hostedHead []factRecord // head AFTER the teammate settled
    45			wantGone   bool         // my fact removed locally
    46			wantSuper  bool         // my fact superseded locally
    47		}{
    48			{
    49				// merge accept removes the candidate — my fact — from the head.
    50				name:   "merge accept retires my fact",
    51				action: factActionMerge,
    52				hostedHead: []factRecord{
    53					{ID: theirs.ID, Paths: paths, Text: theirs.Text, Branch: "main", Origin: factOriginDistilled, Status: factStatusActive},
    54				},
    55				wantGone: true,
    56			},
    57			{
    58				// supersede accept flips MY fact (the target here) to superseded.
    59				name:   "supersede accept supersedes my fact",
    60				action: factActionSupersede,
    61				hostedHead: []factRecord{
    62					{ID: theirs.ID, Paths: paths, Text: theirs.Text, Branch: "main", Origin: factOriginDistilled, Status: factStatusActive},
    63					{ID: mine.ID, Paths: paths, Text: mine.Text, Branch: "main", Origin: factOriginDistilled,
    64						Status: factStatusSuperseded, SupersededBy: theirs.ID},
    65				},
    66				wantSuper: true,
    67			},
    68			{
    69				// reject changes no status; both facts stay as they are.
    70				name:   "reject leaves my fact active",
    71				action: factActionSupersede,
    72				hostedHead: []factRecord{
    73					{ID: theirs.ID, Paths: paths, Text: theirs.Text, Branch: "main", Origin: factOriginDistilled, Status: factStatusActive},
    74					{ID: mine.ID, Paths: paths, Text: mine.Text, Branch: "main", Origin: factOriginDistilled, Status: factStatusActive},
    75				},
    76			},
    77		} {
    78			t.Run(tc.name, func(t *testing.T) {
    79				f := newVerifyFixture(t)
    80				f.writeFacts(t, "main", []factRecord{theirs, mine})
    81	
    82				// For merge the candidate is retired; for supersede the target is.
    83				p := factProposal{Action: tc.action, Branch: "main", ProposedBy: "member-C"}
    84				if tc.action == factActionMerge {
    85					p.CandidateID, p.TargetID = mine.ID, theirs.ID
    86				} else {
    87					p.CandidateID, p.TargetID = theirs.ID, mine.ID
    88				}
    89				if err := writeFactProposals(f.storage.BrainDir, "main", []factProposal{p}); err != nil {
    90					t.Fatal(err)
    91				}
    92				// It reached the hosted set once, and is now absent from it: settled.
    93				if err := writeSharedProposalLedger(f.storage.BrainDir, "main", map[string]struct{}{
    94					factsync.ProposalID(p): {},
    95				}); err != nil {
    96					t.Fatal(err)
    97				}
    98	
    99				if err := reconcileLocalProposalQueue(f.storage.BrainDir, "main", []factsync.OpenProposal{}, tc.hostedHead, f.now); err != nil {
   100					t.Fatalf("reconcile: %v", err)
   101				}
   102	
   103				facts, err := loadFacts(f.storage.BrainDir, "main")
   104				if err != nil {
   105					t.Fatal(err)
   106				}
   107				idx := indexOfFact(facts, mine.ID)
   108				switch {
   109				case tc.wantGone:
   110					if idx >= 0 {
   111						t.Fatalf("merge settlement did not remove my retired fact locally: %+v", facts)
   112					}
   113				case tc.wantSuper:
   114					if idx < 0 {
   115						t.Fatalf("my fact vanished instead of being superseded: %+v", facts)
   116					}
   117					if facts[idx].Status != factStatusSuperseded {
   118						t.Fatalf("supersede settlement did not stick locally: status=%s", facts[idx].Status)
   119					}
   120				default:
   121					if idx < 0 || facts[idx].Status != factStatusActive {
   122						t.Fatalf("reject should not have changed my fact: %+v", facts)
   123					}
   124				}
   125	
   126				// Either way the settled entry must leave the local queue.
   127				queued, qErr := loadFactProposals(f.storage.BrainDir, "main")
   128				if qErr != nil {
   129					t.Fatal(qErr)
   130				}
   131				if len(queued) != 0 {
   132					t.Fatalf("settled proposal still queued locally: %+v", queued)
   133				}
   134			})
   135		}
   136	}
