   274		a := factRecord{ID: "fact:aaa", Paths: paths, Text: "canary", Branch: "main", Status: factStatusActive}
   275		b := factRecord{ID: "fact:bbb", Paths: paths, Text: "blue-green", Branch: "main", Status: factStatusActive}
   276		p := factProposal{Action: factActionSupersede, CandidateID: a.ID, TargetID: b.ID, Branch: "main", ProposedBy: "member-A"}
   277	
   278		for _, tc := range []struct {
   279			name string
   280			head []factRecord
   281			want bool
   282		}{
   283			{"both active: still a live conflict", []factRecord{a, b}, true},
   284			{"candidate merged away", []factRecord{b}, false},
   285			{"target gone", []factRecord{a}, false},
   286			{"head empty", nil, false},
   287			{
   288				"target superseded by the candidate: settled as asked",
   289				[]factRecord{a, {ID: b.ID, Paths: paths, Branch: "main", Status: factStatusSuperseded, SupersededBy: a.ID}},
   290				false,
   291			},
   292			{
   293				"candidate superseded by the target: settled the other way",
   294				[]factRecord{{ID: a.ID, Paths: paths, Branch: "main", Status: factStatusSuperseded, SupersededBy: b.ID}, b},
   295				false,
   296			},
   297		} {
   298			t.Run(tc.name, func(t *testing.T) {
   299				if got := proposalStillOpenAgainst(tc.head, p); got != tc.want {
   300					t.Fatalf("proposalStillOpenAgainst = %v, want %v", got, tc.want)
   301				}
   302			})
   303		}
   304	}
   305	
   306	// TestReconcileKeepsSettledEntryWhenHeadUnavailable guards the ordering. Pruning a
   307	// settled entry is only safe once its settlement has been mirrored into local facts.
   308	// With no readable shared head there is nothing to mirror FROM, so dropping the entry
   309	// would leave the retired fact active locally with no record left to reconcile it
   310	// against — silently reintroducing the very defect the mirroring closes.
   311	func TestReconcileKeepsSettledEntryWhenHeadUnavailable(t *testing.T) {
   312		f := newVerifyFixture(t)
   313		paths := normalizeFactPaths([]string{"ops.deploy.strategy"})
   314		mine := factRecord{ID: "fact:aaa", Paths: paths, Text: "canary", Branch: "main", Status: factStatusActive}
   315		theirs := factRecord{ID: "fact:bbb", Paths: paths, Text: "blue-green", Branch: "main", Status: factStatusActive}
   316		f.writeFacts(t, "main", []factRecord{mine, theirs})
   317	
   318		p := factProposal{Action: factActionMerge, CandidateID: mine.ID, TargetID: theirs.ID, Branch: "main", ProposedBy: "member-C"}
   319		if err := writeFactProposals(f.storage.BrainDir, "main", []factProposal{p}); err != nil {
   320			t.Fatal(err)
   321		}
   322		if err := writeSharedProposalLedger(f.storage.BrainDir, "main", map[string]struct{}{factsync.ProposalID(p): {}}); err != nil {
   323			t.Fatal(err)
   324		}
   325	
   326		// Settled hosted-side (absent from the open set) but the head is unavailable.
   327		if err := reconcileLocalProposalQueue(f.storage.BrainDir, "main", []factsync.OpenProposal{}, nil, f.now); err != nil {
   328			t.Fatalf("reconcile: %v", err)
   329		}
   330	
   331		queued, err := loadFactProposals(f.storage.BrainDir, "main")
   332		if err != nil {
   333			t.Fatal(err)
   334		}
   335		if len(queued) != 1 {
   336			t.Fatalf("settled entry was pruned with no head to mirror from; it can never be reconciled now: %+v", queued)
   337		}
   338		// And local facts must be untouched — no half-applied settlement.
   339		facts, err := loadFacts(f.storage.BrainDir, "main")
   340		if err != nil {
   341			t.Fatal(err)
   342		}
   343		if indexOfFact(facts, mine.ID) < 0 {
   344			t.Fatal("local fact was retired without a head to justify it")
   345		}
   346	}
   347	
   348	// TestFactsProposalsApplyMirrorsIntoLocalFactsImmediately pins the member's own view.
   349	// `facts sync` reconciles settlements eventually, but the member who just ran
   350	// `facts proposals apply` must not keep seeing the pre-settlement state in their own
   351	// facts until their next sync — a local view contradicting the decision they just made.
   352	func TestFactsProposalsApplyMirrorsIntoLocalFactsImmediately(t *testing.T) {
   353		f, _, open := newHostedProposalsFixture(t)
   354	
   355		// The fixture's hosted head holds the pair; give this member the same two facts
   356		// locally, which is the state a member who had synced would be in.
   357		paths := normalizeFactPaths([]string{"ops.deploy.strategy"})
   358		target := factRecord{
   359			ID: open.Proposal.TargetID, Paths: paths, Text: "deploys use blue-green cutover",
   360			Branch: "main", Origin: factOriginDistilled, Status: factStatusActive, CreatedAt: f.now, UpdatedAt: f.now,
   361		}
   362		candidate := factRecord{
   363			ID: open.Proposal.CandidateID, Paths: paths, Text: "deploys use in-place rolling restart",
   364			Branch: "main", Origin: factOriginDistilled, Status: factStatusActive, CreatedAt: f.now, UpdatedAt: f.now,
   365		}
   366		f.writeFacts(t, "main", []factRecord{target, candidate})
   367	
   368		out, err := execute(t, NewRootCommand(f.opts), "facts", "proposals", "apply", open.ID,
   369			"--repo-id", "repo-01HZZ", "--branch", "main")
   370		if err != nil {
   371			t.Fatalf("apply: %v\n%s", err, out)
   372		}
   373	
   374		facts, err := loadFacts(f.storage.BrainDir, "main")
   375		if err != nil {
   376			t.Fatal(err)
   377		}
   378		// The fixture's proposal is a supersede: accepting it retires the TARGET.
   379		ti := indexOfFact(facts, target.ID)
   380		if ti < 0 {
   381			t.Fatalf("target vanished from local facts entirely: %+v", facts)
   382		}
   383		if facts[ti].Status != factStatusSuperseded {
   384			t.Fatalf("local facts still show the pre-settlement state after apply: status=%s", facts[ti].Status)
   385		}
   386		if facts[ti].SupersededBy != candidate.ID {
   387			t.Fatalf("supersede did not point at the winning candidate: %q", facts[ti].SupersededBy)
   388		}
   389	}

