    11	func TestFactRecordIDStableAcrossPathOrder(t *testing.T) {
    12		a := factRecordID("Use tabs, not spaces", []string{"preferences.coding.style", "project.tooling.stack"})
    13		b := factRecordID("Use tabs, not spaces", []string{"preferences.coding.style", "project.tooling.stack"})
    14		if a != b {
    15			t.Fatalf("id not deterministic: %s != %s", a, b)
    16		}
    17		// Casing and surrounding whitespace must not change the id.
    18		c := factRecordID("  use TABS, not spaces  ", []string{"preferences.coding.style", "project.tooling.stack"})
    19		if a != c {
    20			t.Fatalf("id should ignore casing/whitespace: %s != %s", a, c)
    21		}
    22		// A different statement must produce a different id.
    23		d := factRecordID("Use spaces, not tabs", []string{"preferences.coding.style", "project.tooling.stack"})
    24		if a == d {
    25			t.Fatalf("distinct statements collided: %s", a)
    26		}
