    29	func TestNormalizeFactPaths(t *testing.T) {
    30		tests := []struct {
    31			name string
    32			in   []string
    33			want []string
    34		}{
    35			{"sorts and dedupes", []string{"project.tooling.stack", "architecture.data.flow", "project.tooling.stack"}, []string{"architecture.data.flow", "project.tooling.stack"}},
    36			{"drops malformed, lowercases the rest", []string{"too.few", "Architecture.Data.Flow", "ok.one.two"}, []string{"architecture.data.flow", "ok.one.two"}},
    37			{"caps at two", []string{"a.b.c", "d.e.f", "g.h.i"}, []string{"a.b.c", "d.e.f"}},
    38			{"lowercases and trims", []string{"  PREFERENCES.coding.STYLE "}, []string{"preferences.coding.style"}},
    39			{"hyphens invalid", []string{"ci-cd.build.step"}, nil},
    40		}
    41		for _, tt := range tests {
    42			t.Run(tt.name, func(t *testing.T) {
    43				got := normalizeFactPaths(tt.in)
    44				if len(got) != len(tt.want) {
    45					t.Fatalf("got %v, want %v", got, tt.want)
    46				}
    47				for i := range got {
    48					if got[i] != tt.want[i] {
    49						t.Fatalf("got %v, want %v", got, tt.want)
    50					}
    51				}
    52			})
    53		}
    54	}
