    56	func TestValidFactPath(t *testing.T) {
    57		valid := []string{"preferences.coding.style", "a.b.c", "ci_cd.build.step", "x1.y2.z3"}
    58		invalid := []string{"", "a.b", "a.b.c.d", "A.b.c", "ci-cd.build.step", "1a.b.c", "a..c", "a.b.c "}
    59		for _, p := range valid {
    60			if !validFactPath(p) {
    61				t.Errorf("expected valid: %q", p)
    62			}
    63		}
    64		for _, p := range invalid {
    65			if validFactPath(p) {
    66				t.Errorf("expected invalid: %q", p)
    67			}
    68		}
    69	}
