   167	func TestUpsertFactDedupesAndUnionsProvenance(t *testing.T) {
   168		now := time.Date(2026, 6, 4, 12, 0, 0, 0, time.UTC)
   169		later := now.Add(time.Hour)
   170		paths := normalizeFactPaths([]string{"project.tooling.stack"})
   171		id := factRecordID("Uses Go 1.26", paths)
   172		base := factRecord{
   173			ID:         id,
   174			Paths:      paths,
   175			Text:       "Uses Go 1.26",
   176			Origin:     factOriginDistilled,
   177			Status:     factStatusActive,
   178			Provenance: []factAnchor{{SessionID: "s1", Line: 10}},
   179			CreatedAt:  now,
   180			UpdatedAt:  now,
   181		}
   182		set := upsertFact(nil, base)
   183	
   184		// Re-distilling the same statement from a new turn unions provenance,
   185		// does not duplicate the record, and advances UpdatedAt.
   186		dup := base
   187		dup.Provenance = []factAnchor{{SessionID: "s2", Line: 20}}
   188		dup.UpdatedAt = later
   189		set = upsertFact(set, dup)
   190	
   191		if len(set) != 1 {
   192			t.Fatalf("expected dedupe to one record, got %d", len(set))
   193		}
   194		if len(set[0].Provenance) != 2 {
   195			t.Fatalf("expected unioned provenance of 2, got %d", len(set[0].Provenance))
   196		}
   197		if !set[0].UpdatedAt.Equal(later) {
   198			t.Fatalf("expected UpdatedAt to advance to %v, got %v", later, set[0].UpdatedAt)
   199		}
   200	
   201		// A re-submission with an already-seen anchor must not grow provenance.
   202		set = upsertFact(set, dup)
   203		if len(set[0].Provenance) != 2 {
   204			t.Fatalf("anchor union not idempotent: got %d", len(set[0].Provenance))
   205		}
   206	
   207		// A genuinely different fact is appended.
   208		other := base
   209		other.Text = "Uses Rust"
   210		other.ID = factRecordID(other.Text, paths)
   211		set = upsertFact(set, other)
   212		if len(set) != 2 {
   213			t.Fatalf("expected distinct fact appended, got %d", len(set))
   214		}
   215	}
