   258	func TestSummarizeFactSource(t *testing.T) {
   259		now := time.Date(2026, 6, 4, 12, 0, 0, 0, time.UTC)
   260		// Every record carries an id, because that is what makes it a fact.
   261		// summarizeFactSource counts only records that have one (see isFactRecord),
   262		// so the fixture has to be a store of real facts rather than a bag of
   263		// half-populated structs.
   264		byBranch := map[string][]factRecord{
   265			"main": {
   266				{ID: "fact:main-1", Origin: factOriginDistilled, Status: factStatusActive, Provenance: []factAnchor{{SessionID: "s1", Verified: true}}},
   267				{ID: "fact:main-2", Origin: factOriginAuthored, Status: factStatusActive, Provenance: []factAnchor{{SessionID: "s2"}}},
   268			},
   269			"feature": {
   270				{ID: "fact:feature-1", Origin: factOriginDistilled, Status: factStatusSuperseded, Provenance: []factAnchor{{SessionID: "s3"}}},
   271			},
   272		}
   273		source := summarizeFactSource(now, byBranch, 100, 7, 4, []string{"w"})
   274		if source.Facts != 3 {
   275			t.Errorf("Facts = %d, want 3", source.Facts)
   276		}
   277		if source.Proposals != 4 {
   278			t.Errorf("Proposals = %d, want 4", source.Proposals)
   279		}
   280		if source.Distilled != 2 || source.Authored != 1 {
   281			t.Errorf("origin counts wrong: distilled=%d authored=%d", source.Distilled, source.Authored)
   282		}
   283		if source.Superseded != 1 {
   284			t.Errorf("Superseded = %d, want 1", source.Superseded)
   285		}
   286		if source.Verified != 1 || source.Unsigned != 2 {
   287			t.Errorf("anchor counts wrong: verified=%d unsigned=%d", source.Verified, source.Unsigned)
   288		}
   289		if source.ChunksScanned != 100 || source.ChunksDistilled != 7 {
   290			t.Errorf("chunk counts wrong: scanned=%d distilled=%d", source.ChunksScanned, source.ChunksDistilled)
   291		}
   292		if len(source.Branches) != 2 || source.Branches[0] != "feature" || source.Branches[1] != "main" {
   293			t.Errorf("branches not sorted: %v", source.Branches)
   294		}
   295		if source.TaxonomyPath != factsTaxonomyPath {
   296			t.Errorf("TaxonomyPath = %q, want %q", source.TaxonomyPath, factsTaxonomyPath)
   297		}
   298	
   299		// A stored line that parses but carries no id is not a fact and must never
   300		// be declared as one: counting it here is how a damaged store re-declared
   301		// its own damage as whole on the next `remember` or `refresh`, hiding the
   302		// loss from the integrity cross-check that reads this number back.
   303		byBranch["main"] = append(byBranch["main"], factRecord{Status: factStatusActive, Origin: factOriginAuthored})
   304		if got := summarizeFactSource(now, byBranch, 100, 7, 4, nil).Facts; got != 3 {
   305			t.Errorf("Facts = %d after adding an id-less line, want 3", got)
   306		}
   307	}
