 27	// executeSplit runs a command with stdout and stderr captured separately, so
 28	// tests can assert both a parseable stdout contract and the bounded stderr
 29	// diagnostic at once (the shared execute helper merges the two streams).
 30	func executeSplit(t *testing.T, cmd *cobra.Command, args ...string) (stdout, stderr string, err error) {
 31		t.Helper()
 32		var out, errBuf bytes.Buffer
 33		cmd.SetOut(&out)
 34		cmd.SetErr(&errBuf)
 35		cmd.SetArgs(args)
 36		err = cmd.Execute()
 37		return out.String(), errBuf.String(), err
 38	}
