411	func TestVitalityConcurrentAppendsAreLossless(t *testing.T) {
412		brainDir := t.TempDir()
413		branch := "main"
414		now := time.Date(2026, 6, 8, 12, 0, 0, 0, time.UTC)
415		const workers = 32
416	
417		start := make(chan struct{})
418		errs := make(chan error, workers)
419		var wg sync.WaitGroup
420		for i := 0; i < workers; i++ {
421			i := i
422			wg.Add(1)
423			go func() {
424				defer wg.Done()
425				<-start
426				events := []vitalityEvent{
427					{Type: vitalityEventServed, FactID: "fact:shared", At: now.Add(time.Duration(i) * time.Second), Surface: "recall", Branch: branch},
428					{Type: vitalityEventServed, FactID: fmt.Sprintf("fact:unique-%02d", i), At: now, Surface: "query", Branch: branch},
429				}
430				errs <- appendVitalityEventsBoundedWithLockTimeout(
431					brainDir, branch, events, factsVitalityLogMaxBytes, losslessConcurrencyTestLockTimeout,
432				)
433			}()
434		}
435		close(start)
436		wg.Wait()
437		close(errs)
438		for err := range errs {
439			if err != nil {
440				t.Fatalf("concurrent append: %v", err)
441			}
442		}
443	
444		rollup, stats, err := compactVitality(brainDir, branch)
445		if err != nil {
446			t.Fatalf("compact: %v", err)
447		}
448		if stats.Malformed != 0 {
449			t.Fatalf("interleaved appends corrupted the log: %+v", stats)
450		}
451		if got := rollup.Facts["fact:shared"]; got == nil || got.Served != workers {
452			t.Fatalf("shared fact receipts = %+v, want %d", got, workers)
453		}
454		total := 0
455		for _, entry := range rollup.Facts {
456			total += entry.Served
457		}
458		if total != workers*2 || len(rollup.Facts) != workers+1 {
459			t.Fatalf("lost receipts: total=%d facts=%d", total, len(rollup.Facts))
460		}
461		if got := rollup.Facts["fact:shared"].LastServed; !got.Equal(now.Add(time.Duration(workers-1) * time.Second)) {
462			t.Fatalf("last_served = %s", got)
463		}
464	}
