   328	// chunkFailWriter records each Write separately and fails once the recorded
   329	// byte total reaches failAfter, so a test can prove writeText streams (rather
   330	// than buffering the whole body and writing it once).
   331	type chunkFailWriter struct {
   332		writes    []string
   333		total     int
   334		failAfter int
   335	}
   336	
   337	func (w *chunkFailWriter) Write(p []byte) (int, error) {
   338		if w.total >= w.failAfter {
   339			return 0, errVitalityTestOutput
   340		}
   341		w.writes = append(w.writes, string(p))
   342		w.total += len(p)
   343		return len(p), nil
   344	}
