FILE:internal/cli/export_newest_first_test.go
     1	package cli
     2	
     3	import "testing"
     4	
     5	// TestCheckpointEntriesFromIDs_LimitKeepsTheNewest pins that --checkpoint-limit
     6	// keeps the most recent checkpoints across BOTH ID formats.
     7	//
     8	// A ULID encodes a millisecond timestamp in its leading characters and is
     9	// time-sortable; a legacy 12-hex ID is random throughout and carries no time.
    10	// Sorting the mixed set as reversed strings ordered by byte value instead of
    11	// recency — hex is lowercase, ULIDs are uppercase Crockford base32, so every
    12	// hex ID beginning a-f sorted above every ULID. Under a limit that discarded
    13	// the newest checkpoints (the ULIDs the git-refs backend mints) and kept the
    14	// oldest ones from the pre-migration branch.
    15	func TestCheckpointEntriesFromIDs_LimitKeepsTheNewest(t *testing.T) {
    16		t.Parallel()
    17	
    18		const legacyHex = "fedcba987654" // legacy 12-hex, no recoverable time
    19		const olderULID = "01AAAAAAAA4YW6J5M9GP655HZN"
    20		const newerULID = "01ZZZZZZZZ4YW6J5M9GP655HZN"
    21	
    22		for _, id := range []string{olderULID, newerULID} {
    23			if _, ok := checkpointULIDTime(id); !ok {
    24				t.Fatalf("fixture %q is not a recognized ULID checkpoint ID", id)
    25			}
    26		}
    27	
    28		ids := map[string]struct{}{
    29			legacyHex: {},
    30			olderULID: {},
    31			newerULID: {},
    32		}
    33	
    34		entries := checkpointEntriesFromIDs(ids, 2)
    35		if len(entries) != 2 {
    36			t.Fatalf("got %d entries, want 2", len(entries))
    37		}
    38		got := []string{entries[0].CheckpointID, entries[1].CheckpointID}
    39		want := []string{newerULID, olderULID}
    40		for i := range want {
    41			if got[i] != want[i] {
    42				t.Fatalf("limit kept %v, want the two newest %v", got, want)
    43			}
    44		}
    45	}
    46	
    47	// TestCheckpointEntriesFromIDs_LegacyOnlyKeepsDescendingOrder keeps the previous
    48	// behavior for a repo that has never minted a ULID: no time is recoverable from
    49	// any of the IDs, so descending ID order stands.
    50	func TestCheckpointEntriesFromIDs_LegacyOnlyKeepsDescendingOrder(t *testing.T) {
    51		t.Parallel()
    52	
    53		ids := map[string]struct{}{
    54			"aaaaaaaaaaaa": {},
    55			"ffffffffffff": {},
    56			"555555555555": {},
    57		}
    58	
    59		entries := checkpointEntriesFromIDs(ids, 0)
    60		want := []string{"ffffffffffff", "aaaaaaaaaaaa", "555555555555"}
    61		if len(entries) != len(want) {
    62			t.Fatalf("got %d entries, want %d", len(entries), len(want))
    63		}
    64		for i := range want {
    65			if entries[i].CheckpointID != want[i] {
    66				t.Fatalf("order %v, want %v", entries, want)
    67			}
    68		}
    69	}
FILE:internal/cli/export_sync_remote_test.go
     1	package cli
     2	
     3	import (
     4		"context"
     5		"errors"
     6		"os"
     7		"path/filepath"
     8		"sort"
     9		"testing"
    10	)
    11	
    12	// Checkpoints do not necessarily sync to a remote named "origin". The CLI
    13	// elects ONE remote to carry them — strategy_options.checkpoint_push_remote,
    14	// then a remote a past push captured, then "origin", then the sole/first remote
    15	// in .git/config order — and its read paths consult that elected remote first
    16	// with "origin" behind it as a legacy tier
    17	// (cmd/entire/cli/strategy/checkpoint_read_remotes.go). The export reader looked
    18	// only at the local branch and origin's tracking ref, so a clone whose elected
    19	// remote is named anything else had checkpoints the brain never saw.
    20	
    21	const (
    22		remoteFork     = "fork"
    23		forkTrackingV1 = "refs/remotes/fork/entire/checkpoints/v1"
    24	)
    25	
    26	// syncRemoteRunner scripts a repository with the given remotes in .git/config
    27	// order and one checkpoint tree per named tracking ref.
    28	func syncRemoteRunner(remotes []string, trees map[string]string) *fakeCommandRunner {
    29		var config string
    30		for _, name := range remotes {
    31			config += "remote." + name + ".url https://example.test/" + name + ".git\n"
    32		}
    33		responses := map[string]fakeCommandResponse{
    34			fakeCommandKey("git", "config", "--local", "--get-regexp", `^remote\..*\.url$`): {stdout: config},
    35			fakeCommandKey("git", "rev-parse", "--git-common-dir"):                          {stdout: ".git\n"},
    36			fakeCommandKey("git", "ls-tree", "-r", "--name-only", v1MainRef):                {err: errors.New("no local checkpoint branch")},
    37			fakeCommandKey("git", "ls-tree", "-r", "--name-only", v1OriginRef):              {err: errors.New("no origin tracking ref")},
    38		}
    39		for ref, tree := range trees {
    40			responses[fakeCommandKey("git", "ls-tree", "-r", "--name-only", ref)] = fakeCommandResponse{stdout: tree}
    41		}
    42		return &fakeCommandRunner{responses: responses}
    43	}
    44	
    45	func sourceIDs(sources map[string]checkpointSnapshotSource) []string {
    46		ids := make([]string, 0, len(sources))
    47		for id := range sources {
    48			ids = append(ids, id)
    49		}
    50		sort.Strings(ids)
    51		return ids
    52	}
    53	
    54	func writeRepoSettings(t *testing.T, repoDir, name, body string) {
    55		t.Helper()
    56		settingsDir := filepath.Join(repoDir, ".entire")
    57		if err := os.MkdirAll(settingsDir, 0o700); err != nil {
    58			t.Fatal(err)
    59		}
    60		if err := os.WriteFile(filepath.Join(settingsDir, name), []byte(body), 0o600); err != nil {
    61			t.Fatal(err)
    62		}
    63	}
    64	
    65	// TestLoadAggregateCheckpointSources_ReadsConfiguredPushRemote pins the
    66	// checkpoint_push_remote tier: the named remote's tracking ref is read.
    67	func TestLoadAggregateCheckpointSources_ReadsConfiguredPushRemote(t *testing.T) {
    68		t.Parallel()
    69	
    70		repoDir := t.TempDir()
    71		writeRepoSettings(t, repoDir, "settings.local.json", `{"strategy_options":{"checkpoint_push_remote":"fork"}}`)
    72		runner := syncRemoteRunner([]string{"origin", remoteFork}, map[string]string{
    73			forkTrackingV1: "aa/aaaaaaaaaa/metadata.json\naa/aaaaaaaaaa/0/metadata.json\naa/aaaaaaaaaa/0/full.jsonl\n",
    74		})
