     5	// TestCheckpointEntriesFromIDs_LimitKeepsTheNewest pins that --checkpoint-limit
     6	// keeps the most recent checkpoints across BOTH ID formats.
     7	//
     8	// A ULID encodes a millisecond timestamp in its leading characters and is
     9	// time-sortable; a legacy 12-hex ID is random throughout and carries no time.
    10	// Sorting the mixed set as reversed strings ordered by byte value instead of
    11	// recency — hex is lowercase, ULIDs are uppercase Crockford base32, so every
    12	// hex ID beginning a-f sorted above every ULID. Under a limit that discarded
    13	// the newest checkpoints (the ULIDs the git-refs backend mints) and kept the
    14	// oldest ones from the pre-migration branch.
    15	func TestCheckpointEntriesFromIDs_LimitKeepsTheNewest(t *testing.T) {
    16		t.Parallel()
    17	
    18		const legacyHex = "fedcba987654" // legacy 12-hex, no recoverable time
    19		const olderULID = "01AAAAAAAA4YW6J5M9GP655HZN"
    20		const newerULID = "01ZZZZZZZZ4YW6J5M9GP655HZN"
    21	
    22		for _, id := range []string{olderULID, newerULID} {
    23			if _, ok := checkpointULIDTime(id); !ok {
    24				t.Fatalf("fixture %q is not a recognized ULID checkpoint ID", id)
    25			}
    26		}
    27	
    28		ids := map[string]struct{}{
    29			legacyHex: {},
    30			olderULID: {},
    31			newerULID: {},
    32		}
    33	
    34		entries := checkpointEntriesFromIDs(ids, 2)
    35		if len(entries) != 2 {
    36			t.Fatalf("got %d entries, want 2", len(entries))
    37		}
    38		got := []string{entries[0].CheckpointID, entries[1].CheckpointID}
    39		want := []string{newerULID, olderULID}
    40		for i := range want {
    41			if got[i] != want[i] {
    42				t.Fatalf("limit kept %v, want the two newest %v", got, want)
    43			}
    44		}
    45	}
