    26	// syncRemoteRunner scripts a repository with the given remotes in .git/config
    27	// order and one checkpoint tree per named tracking ref.
    28	func syncRemoteRunner(remotes []string, trees map[string]string) *fakeCommandRunner {
    29		var config string
    30		for _, name := range remotes {
    31			config += "remote." + name + ".url https://example.test/" + name + ".git\n"
    32		}
    33		responses := map[string]fakeCommandResponse{
    34			fakeCommandKey("git", "config", "--local", "--get-regexp", `^remote\..*\.url$`): {stdout: config},
    35			fakeCommandKey("git", "rev-parse", "--git-common-dir"):                          {stdout: ".git\n"},
    36			fakeCommandKey("git", "ls-tree", "-r", "--name-only", v1MainRef):                {err: errors.New("no local checkpoint branch")},
    37			fakeCommandKey("git", "ls-tree", "-r", "--name-only", v1OriginRef):              {err: errors.New("no origin tracking ref")},
    38		}
    39		for ref, tree := range trees {
    40			responses[fakeCommandKey("git", "ls-tree", "-r", "--name-only", ref)] = fakeCommandResponse{stdout: tree}
    41		}
    42		return &fakeCommandRunner{responses: responses}
    43	}
