   214		}}
   215		findings := semanticDoctorFindings(report)
   216		byName := doctorFindingsByName(findings)
   217		provider, ok := byName["semantic provider"]
   218		if !ok {
   219			t.Fatalf("doctor dropped the provider finding: %+v", findings)
   220		}
   221		if provider.scope() != doctorScopeEnvironment {
