   274	// --- defect 4a: facts proposals --json printed help text -------------------
   275	
   276	// TestFactsProposalsJSONDoesNotPrintHelp pins the one --json violation out of
   277	// the 92 nodes that advertise the flag: the group node printed human help to
   278	// stdout and exited 0, so a machine caller got prose labelled as success.
   279	func TestFactsProposalsJSONDoesNotPrintHelp(t *testing.T) {
   280		opts := Options{Version: "test"}
   281		stdout, stderr, err := executeSplit(t, NewRootCommand(opts), "facts", "proposals", "--json")
   282		if err == nil {
   283			t.Fatalf("facts proposals --json must not exit 0 with no result\nstdout:\n%s", stdout)
   284		}
