   286			t.Fatalf("facts proposals --json wrote non-JSON to stdout:\n%s", stdout)
   287		}
   288		var envelope commandJSONError
   289		if jsonErr := json.Unmarshal([]byte(stderr), &envelope); jsonErr != nil {
   290			t.Fatalf("facts proposals --json did not emit a JSON error envelope: %v\n%s", jsonErr, stderr)
   291		}
   292		if !strings.Contains(envelope.Message, "requires a subcommand") {
   293			t.Fatalf("JSON error does not say what is missing: %+v", envelope)
   294		}
   295		for _, verb := range []string{"list", "show", "apply", "reject", "repair"} {
   296			if !strings.Contains(envelope.Message, verb) {
   297				t.Fatalf("JSON error does not name the %q verb: %+v", verb, envelope)
   298			}
