   311	// --- defect 4b: refresh index exited 1 when there was nothing to do --------
   312	
   313	// TestRefreshIndexIsIdempotent is the scripted-loop defect: `refresh index`
   314	// failed on every run after the first, so any refresh sequence containing the
   315	// documented step could be green exactly once.
   316	func TestRefreshIndexIsIdempotent(t *testing.T) {
   317		repoDir := t.TempDir()
   318		env := semanticTestEnv(t, repoDir)
   319		runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot(semanticSchemaVersion))
   320		opts := Options{Env: env, Runner: runner, Now: time.Now}
   321		for attempt := 1; attempt <= 3; attempt++ {
   322			cmd := &cobra.Command{Use: "index"}
   323			var out bytes.Buffer
   324			cmd.SetOut(&out)
   325			cmd.SetErr(&out)
   326			if err := runSemanticIndex(cmd.Context(), cmd, opts, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
   327				t.Fatalf("refresh index attempt %d failed: %v\n%s", attempt, err, out.String())
   328			}
