 15	type fakeCommandRunner struct {
 16		responses           map[string]fakeCommandResponse
 17		sequences           map[string][]fakeCommandResponse
 18		semanticSnapshotAny *fakeCommandResponse
 19		// fallback answers commands no explicit response covers, so a fixture can
 20		// script a WALKER (any revision range at any --max-count) instead of
 21		// pre-baking the one range a caller happened to ask for last. Explicit
 22		// responses still win, so a test can force a specific failure.
 23		fallback func(name string, args []string) (fakeCommandResponse, bool)
 24		calls    []fakeCommandCall
 25	}
 26	
 27	type fakeCommandResponse struct {
 28		stdout string
 29		stderr string
 30		err    error
 31	}
 32	
 33	type runOnlyCommandRunner struct {
 34		inner *fakeCommandRunner
 35	}
 36	
 37	func (r runOnlyCommandRunner) Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
 38		return r.inner.Run(ctx, dir, name, args...)
 39	}
 40	
 41	type fakeCommandCall struct {
 42		dir         string
 43		name        string
 44		args        []string
 45		env         map[string]string
 46		hasDeadline bool
 47	}
 48	
 49	func (r *fakeCommandRunner) Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
 50		return r.run(ctx, dir, nil, name, args...)
 51	}
 52	
 53	func (r *fakeCommandRunner) RunWithEnv(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error) {
 54		return r.run(ctx, dir, env, name, args...)
 55	}
 56	
 57	func (r *fakeCommandRunner) run(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error) {
 58		key := fakeCommandKey(name, args...)
 59		var hasDeadline bool
 60		if ctx != nil {
 61			_, hasDeadline = ctx.Deadline()
 62		}
 63		r.calls = append(r.calls, fakeCommandCall{
 64			dir:         dir,
 65			name:        name,
 66			args:        append([]string(nil), args...),
 67			env:         mapsClone(env),
 68			hasDeadline: hasDeadline,
 69		})
 70	
 71		if sequence, ok := r.sequences[key]; ok && len(sequence) > 0 {
 72			response := sequence[0]
 73			r.sequences[key] = sequence[1:]
 74			return []byte(response.stdout), []byte(response.stderr), response.err
 75		}
 76	
 77		response, ok := r.responses[key]
 78		if !ok {
 79			if r.semanticSnapshotAny != nil && fakeCommandIsSemanticSnapshotAnyRepo(name, args) {
 80				response := *r.semanticSnapshotAny
 81				return []byte(response.stdout), []byte(response.stderr), response.err
 82			}
 83			if key == fakeCommandKey("git", "symbolic-ref", "--quiet", "--short", "refs/remotes/origin/HEAD") {
 84				return []byte("origin/main\n"), nil, nil
 85			}
 86			// An unscripted fixture describes an ORDINARY machine, and an ordinary
 87			// machine has git. `git --version` reads no repository, so it cannot
 88			// fail for anything a fixture is modelling about a directory -- and the
 89			// diagnosis that separates "git is not installed" from "this is not a
 90			// repository" asks exactly this question. Leaving it unscripted made
 91			// every non-repository fixture also claim git was missing, which is how
 92			// four of them came to assert the wrong message. A fixture that really
 93			// does mean "no git on this machine" scripts this call to fail.
 94			if name == "git" && len(args) == 1 && args[0] == "--version" {
 95				return []byte("git version 2.48.1\n"), nil, nil
 96			}
 97			if r.fallback != nil {
 98				if response, handled := r.fallback(name, args); handled {
 99					return []byte(response.stdout), []byte(response.stderr), response.err
100				}
101			}
102			if key == fakeCommandKey("entire", "graph", "version", "--json") {
103				return []byte(`{"provider":"entire-graph","version":"test"}`), nil, nil
104			}
105			return nil, nil, errors.New("unexpected command: " + key)
106		}
107		return []byte(response.stdout), []byte(response.stderr), response.err
108	}
