174	func fakeCommandIsSemanticSnapshotAnyRepo(name string, args []string) bool {
175		if name != "entire" || len(args) < 6 {
176			return false
177		}
178		if args[0] != "graph" || args[1] != "snapshot" || args[2] != "--repo" {
179			return false
180		}
181		for _, arg := range args {
182			if arg == "--ignore-file" {
183				return false
184			}
185		}
186		return true
187	}
