160	type fakeCommandStream struct {
161		stdout *strings.Reader
162		stderr []byte
163		err    error
164	}
165	
166	func (s *fakeCommandStream) Stdout() io.Reader     { return s.stdout }
167	func (s *fakeCommandStream) Wait() ([]byte, error) { return s.stderr, s.err }
168	func (s *fakeCommandStream) Close() error          { return nil }
