121	// Stream mirrors Run for tests, exposing the configured stdout as a streaming
122	// reader so the streaming semantic indexer exercises the same fixtures. The
123	// deadline is recorded identically to Run so timeout assertions still hold.
124	func (r *fakeCommandRunner) Stream(ctx context.Context, dir, name string, args ...string) (CommandStream, error) {
125		key := fakeCommandKey(name, args...)
126		var hasDeadline bool
127		if ctx != nil {
128			_, hasDeadline = ctx.Deadline()
129		}
130		r.calls = append(r.calls, fakeCommandCall{
131			dir:         dir,
132			name:        name,
133			args:        append([]string(nil), args...),
134			hasDeadline: hasDeadline,
135		})
136	
137		response := r.lookupResponse(key, name, args)
138		return &fakeCommandStream{
139			stdout: strings.NewReader(response.stdout),
140			stderr: []byte(response.stderr),
141			err:    response.err,
142		}, nil
143	}
144	
145	func (r *fakeCommandRunner) lookupResponse(key, name string, args []string) fakeCommandResponse {
146		if sequence, ok := r.sequences[key]; ok && len(sequence) > 0 {
147			response := sequence[0]
148			r.sequences[key] = sequence[1:]
149			return response
150		}
151		if response, ok := r.responses[key]; ok {
152			return response
153		}
154		if r.semanticSnapshotAny != nil && fakeCommandIsSemanticSnapshotAnyRepo(name, args) {
155			return *r.semanticSnapshotAny
156		}
157		return fakeCommandResponse{err: errors.New("unexpected command: " + key)}
158	}
