    85		srcUnique := factFor(t, "source: prefers tabs", []string{"preferences.coding.style"}, now)
    86		srcUnique.Branch = "feature"
    87		tgtConflict := factFor(t, "target: use Postgres", []string{"project.tooling.stack"}, now)
    88		tgtConflict.Branch = "main"
    89	
    90		source := []factRecord{srcConflict, srcUnique}
    91		target := []factRecord{tgtConflict}
