    95			if promoted != 2 {
    96				t.Fatalf("expected 2 promoted, got %d", promoted)
    97			}
    98			if len(proposals) != 1 {
    99				t.Fatalf("conflict should queue 1 proposal, got %d", len(proposals))
   100			}
   101			for _, f := range merged {
   102				if f.ID == tgtConflict.ID && f.Status != factStatusActive {
   103					t.Errorf("keep-both should keep target active")
   104				}
   105			}
   106			// Promoted facts must be re-stamped onto the target branch.
   107			for _, f := range merged {
   108				if f.Branch != "main" {
   109					t.Errorf("promoted fact not re-stamped to main: %+v", f)
   110				}
   111			}
   112		})
   113	
   114		t.Run("prefer-source", func(t *testing.T) {
   115			merged, proposals, _ := promoteFacts(source, target, "prefer-source", "main", now)
   116			if len(proposals) != 0 {
   117				t.Fatalf("prefer-source should not queue proposals")
   118			}
   119			ti := indexOfFact(merged, tgtConflict.ID)
   120			if merged[ti].Status != factStatusSuperseded {
   121				t.Fatalf("prefer-source should supersede the conflicting target fact")
   122			}
   123		})
   124	
   125		t.Run("prefer-target", func(t *testing.T) {
   126			merged, _, promoted := promoteFacts(source, target, "prefer-target", "main", now)
   127			// The conflicting source fact is dropped; only the unique one promotes.
   128			if promoted != 1 {
   129				t.Fatalf("prefer-target should promote only the non-conflicting fact, got %d", promoted)
   130			}
   131			if indexOfFact(merged, srcConflict.ID) >= 0 {
   132				t.Fatalf("conflicting source fact should be dropped under prefer-target")
