   168	func treeContentHash(t *testing.T, root string) string {
   169		t.Helper()
   170		var paths []string
   171		if err := filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
   172			if err != nil {
   173				return err
   174			}
   175			if !entry.IsDir() {
   176				rel, _ := filepath.Rel(root, path)
   177				rel = filepath.ToSlash(rel)
   178				vitalityLock := filepath.ToSlash(filepath.Join(brainLockDirName, factsVitalityLockName))
   179				if filepath.Base(path) == factsVitalityLogFileName ||
   180					filepath.Base(path) == factsVitalityRollupFileName ||
   181					rel == vitalityLock ||
   182					// The owner sidecar is part of the same artifact as the lock
   183					// above and is rewritten on the same acquisitions. It carries
   184					// the timestamp that used to live INSIDE the lock file, so
   185					// excluding the lock without its sidecar would make this hash
   186					// sensitive to the clock rather than to the brain.
   187					rel == vitalityLock+fileLockOwnerSuffix {
   188					return nil
   189				}
   190				paths = append(paths, path)
   191			}
   192			return nil
   193		}); err != nil {
   194			t.Fatal(err)
   195		}
   196		sort.Strings(paths)
   197		h := sha256.New()
   198		for _, path := range paths {
   199			data, err := os.ReadFile(path)
   200			if err != nil {
   201				t.Fatal(err)
   202			}
   203			rel, _ := filepath.Rel(root, path)
   204			_, _ = h.Write([]byte(rel))
   205			_, _ = h.Write(data)
   206		}
   207		return hex.EncodeToString(h.Sum(nil))
   208	}
