    43	func rankedFactsBM25IDs(scores map[string]float64) []string {
    44		ids := make([]string, 0, len(scores))
    45		for id := range scores {
    46			ids = append(ids, id)
    47		}
    48		sort.Slice(ids, func(i, j int) bool {
    49			if scores[ids[i]] != scores[ids[j]] {
    50				return scores[ids[i]] > scores[ids[j]]
    51			}
    52			return ids[i] < ids[j]
    53		})
    54		return ids
    55	}
