 69	// replaceFactLines overwrites the given 0-based line numbers of a facts.ndjson
 70	// with the replacement text, leaving every other line untouched. The store
 71	// stays readable; only its content stops being facts. It returns the ids the
 72	// replacement destroyed, because writeFacts sorts the store and a caller
 73	// cannot know from the line number alone which fact it just lost.
 74	func replaceFactLines(t *testing.T, path, replacement string, lines ...int) []string {
 75		t.Helper()
 76		data, err := os.ReadFile(path)
 77		if err != nil {
 78			t.Fatal(err)
 79		}
 80		existing := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
 81		var lost []string
 82		for _, n := range lines {
 83			if n < 0 || n >= len(existing) {
 84				t.Fatalf("line %d out of range for a %d-line store", n, len(existing))
 85			}
 86			var record factRecord
 87			if err := json.Unmarshal([]byte(existing[n]), &record); err != nil {
 88				t.Fatalf("line %d is not a fact to begin with: %v", n, err)
 89			}
 90			lost = append(lost, record.ID)
 91			existing[n] = replacement
 92		}
 93		if err := os.WriteFile(path, []byte(strings.Join(existing, "\n")+"\n"), 0o600); err != nil {
 94			t.Fatal(err)
 95		}
 96		return lost
 97	}
