 99	// TestFactStoreIntegrityDetectsOneLostFactAmongFive is the headline case: one
100	// of five lines is replaced with valid JSON that is not a fact record. The
101	// store still reads, so every surface used to report the manifest's 5.
102	func TestFactStoreIntegrityDetectsOneLostFactAmongFive(t *testing.T) {
103		opts, repoDir, brainDir, path := factLossFixture(t)
104	
105		lost := replaceFactLines(t, path, `{"hello":"world"}`, 0)
106	
107		// One subtest per surface, so a regression names the surface it broke.
108		t.Run("cross-check", func(t *testing.T) {
109			integrity := inspectBrainFactStore(brainDir)
110			if integrity.OK() {
111				t.Fatalf("integrity reports a healthy store after a fact was overwritten: %+v", integrity)
112			}
113			if integrity.Mode != factStoreDefectLossy {
114				t.Fatalf("mode = %q, want %q", integrity.Mode, factStoreDefectLossy)
115			}
116			if integrity.Declared != 5 || integrity.Readable != 4 || integrity.Lost() != 1 {
117				t.Fatalf("declared/readable/lost = %d/%d/%d, want 5/4/1", integrity.Declared, integrity.Readable, integrity.Lost())
118			}
119			if integrity.Unusable != 1 {
120				t.Fatalf("unusable = %d, want 1", integrity.Unusable)
121			}
122			if !strings.Contains(integrity.Warning(), "5 declared, 4 readable") {
123				t.Fatalf("warning does not carry both counts: %q", integrity.Warning())
124			}
125			if !strings.Contains(integrity.Warning(), "entire brain refresh") {
126				t.Fatalf("warning does not name the repair command: %q", integrity.Warning())
127			}
128		})
129	
130		// status: the identity line must not print the declared number alone, and
131		// the report must carry the defect for JSON/MCP readers.
132		t.Run("status", func(t *testing.T) {
133			report, err := buildAvailableBrainStatusReport(context.Background(), opts, repoDir)
134			if err != nil {
135				t.Fatalf("status report: %v", err)
136			}
137			if report.Facts == nil || report.Facts.Integrity == nil {
138				t.Fatalf("status facts carries no integrity verdict: %+v", report.Facts)
139			}
140			if report.Facts.Readable() != 4 {
141				t.Fatalf("status facts readable = %d, want 4", report.Facts.Readable())
142			}
143			if !warningsMention(report.Warnings, "4 readable") {
144				t.Fatalf("status warnings do not name the loss: %v", report.Warnings)
145			}
146			statusOut, err := execute(t, NewRootCommand(opts), "status")
147			if err != nil {
148				t.Fatalf("status: %v\n%s", err, statusOut)
149			}
150			if !strings.Contains(statusOut, "5 facts declared, 4 readable") {
151				t.Fatalf("status identity line still reports the declared count as observed:\n%s", statusOut)
152			}
153		})
154	
155		// doctor: an error-level finding (the exit gate is `doctor --fail-on`).
156		t.Run("doctor", func(t *testing.T) {
157			checks, _ := brainDoctorReadOnlyReport(context.Background(), opts, repoDir)
158			state, ok := factsDoctorCheckState(checks)
159			if !ok {
160				t.Fatalf("doctor has no facts check: %+v", checks)
161			}
162			if state != "error" {
163				t.Fatalf("doctor facts = %q, want error", state)
164			}
165		})
166	
167		// verify: its whole job. It must not answer "0 orphaned" and exit 0.
168		t.Run("verify", func(t *testing.T) {
169			verifyOut, verifyErr := execute(t, NewRootCommand(opts), "verify", "--branch", "feature")
170			if verifyErr == nil {
171				t.Fatalf("verify passed over a store that lost a fact:\n%s", verifyOut)
172			}
173			if !strings.Contains(verifyOut, "store integrity") {
174				t.Fatalf("verify did not report the store defect:\n%s", verifyOut)
175			}
176			if !strings.Contains(verifyOut, "5 declared, 4 readable") {
177				t.Fatalf("verify did not name the shortfall:\n%s", verifyOut)
178			}
179		})
180	
181		// facts map: the outline's "(N facts)" is a count of survivors.
182		t.Run("facts-map", func(t *testing.T) {
183			mapOut, mapErr := execute(t, NewRootCommand(opts), "facts", "map", "--branch", "feature")
184			if mapErr == nil {
185				t.Fatalf("facts map exited clean over a lossy store:\n%s", mapOut)
186			}
187			if !strings.Contains(mapOut, "5 declared, 4 readable") {
188				t.Fatalf("facts map did not qualify its counts:\n%s", mapOut)
189			}
190		})
191	
192		// The retrieval note is the most damaging surface: it must not tell the
193		// user their memory was never there.
194		t.Run("retrieval-note", func(t *testing.T) {
195			note := emptyResultBlindSpot(brainDir)
196			if strings.Contains(note, "may genuinely not be in the brain") {
197				t.Fatalf("the note still vouches for the empty after fact loss: %q", note)
198			}
