    58	// TestRankFactsClosedNegativeOutranksPeers locks in the Phase 2 (agent
    59	// utility) ranking rule: among facts that match the query, a closed-negative
    60	// — "this was tried and failed" — outranks similarly-matching peers, because
    61	// it prevents re-exploration rather than just re-derivation. The boost must
    62	// never create a match on its own.
    63	func TestRankFactsClosedNegativeOutranksPeers(t *testing.T) {
