    65		facts := []factRecord{
    66			// Same text-match strength against the query, different kinds. The
    67			// convention is more recent, so without the boost it would win the tie.
    68			{ID: "fact:conv", Kind: factKindConvention, Paths: []string{"workflow.testing.rules"}, Text: "Expansion terms are reviewed in the weekly retrieval sync.", Status: factStatusActive, UpdatedAt: now.Add(time.Hour)},
    69			{ID: "fact:neg", Kind: factKindClosedNegative, Paths: []string{"workflow.testing.rules"}, Text: "Expansion terms were tried for recall and rejected; revisit only with a new model.", Status: factStatusActive, UpdatedAt: now},
    70		}
    71		got := rankFacts(facts, "expansion terms", 10, false)
    72		if len(got) != 2 || got[0].ID != "fact:neg" {
