    11	// hostedHead re-serializes a fact set as the hosted head blob, so a test can
    12	// stage exactly the state a teammate's settlement would have left behind.
    13	func hostedHead(t *testing.T, facts []factRecord) []byte {
    14		t.Helper()
    15		var blob strings.Builder
    16		if err := factmerge.WriteNDJSON(&blob, facts); err != nil {
    17			t.Fatal(err)
    18		}
    19		return []byte(blob.String())
