   138	// TestFactsReviewRefusesToSettleSharedProposalLocally is the regression for the
   139	// missing hosted interlock: settling a published proposal with the local `facts
   140	// review` used to leave the hosted copy open, so a teammate's later apply
   141	// silently overrode this member's decision.
   142	func TestFactsReviewRefusesToSettleSharedProposalLocally(t *testing.T) {
   143		f := newVerifyFixture(t)
   144		paths := normalizeFactPaths([]string{"ops.deploy.strategy"})
   145		target := factRecord{
   146			ID: factRecordID("deploys use blue-green cutover", paths), Paths: paths,
   147			Text: "deploys use blue-green cutover", Branch: "main", Origin: factOriginDistilled, Status: factStatusActive,
   148			CreatedAt: f.now, UpdatedAt: f.now,
   149		}
   150		candidate := factRecord{
   151			ID: factRecordID("deploys use in-place rolling restart", paths), Paths: paths,
   152			Text: "deploys use in-place rolling restart", Branch: "main", Origin: factOriginDistilled, Status: factStatusActive,
   153			CreatedAt: f.now, UpdatedAt: f.now,
   154		}
   155		f.writeFacts(t, "main", []factRecord{target, candidate})
   156	
   157		sharedProposal := factProposal{
   158			Action: factActionSupersede, CandidateID: candidate.ID, TargetID: target.ID,
   159			Branch: "main", ProposedBy: "member-C",
   160		}
   161		if err := writeFactProposals(f.storage.BrainDir, "main", []factProposal{sharedProposal}); err != nil {
   162			t.Fatal(err)
   163		}
   164		if err := writeSharedProposalLedger(f.storage.BrainDir, "main", map[string]struct{}{
   165			factsync.ProposalID(sharedProposal): {},
   166		}); err != nil {
   167			t.Fatal(err)
   168		}
   169	
   170		out, err := execute(t, NewRootCommand(f.opts), "facts", "review", "--apply", candidate.ID)
   171		if err == nil {
   172			t.Fatalf("expected a refusal for a shared proposal, got success:\n%s", out)
   173		}
   174		if !strings.Contains(err.Error(), "facts proposals") {
   175			t.Fatalf("refusal should point at 'facts proposals', got: %v", err)
   176		}
   177	
   178		// The local facts must be untouched — no half-applied settlement.
   179		facts, loadErr := loadFacts(f.storage.BrainDir, "main")
   180		if loadErr != nil {
   181			t.Fatal(loadErr)
   182		}
   183		if ti := indexOfFact(facts, target.ID); ti < 0 || facts[ti].Status != factStatusActive {
   184			t.Fatalf("refused review still mutated local facts: %+v", facts)
   185		}
   186		queued, qErr := loadFactProposals(f.storage.BrainDir, "main")
   187		if qErr != nil || len(queued) != 1 {
   188			t.Fatalf("refused review dropped the queue entry: %v, %d", qErr, len(queued))
   189		}
   190	}
