   328	// chunkFailWriter records each Write separately and fails once the recorded
   329	// byte total reaches failAfter, so a test can prove writeText streams (rather
   330	// than buffering the whole body and writing it once).
   331	type chunkFailWriter struct {
   332		writes    []string
   333		total     int
   334		failAfter int
   335	}
   336	
   337	func (w *chunkFailWriter) Write(p []byte) (int, error) {
   338		if w.total >= w.failAfter {
   339			return 0, errVitalityTestOutput
   340		}
   341		w.writes = append(w.writes, string(p))
   342		w.total += len(p)
   343		return len(p), nil
   344	}
   345	
   346	func TestWriteTextStreamsAndShortCircuitsOnFailure(t *testing.T) {
   347		w := &chunkFailWriter{failAfter: 5}
   348		cmd := &cobra.Command{}
   349		cmd.SetOut(w)
   350		err := writeText(cmd, func(out io.Writer) {
   351			fmt.Fprint(out, "aaa") // 3 bytes, accepted
   352			fmt.Fprint(out, "bbb") // total now 6 -> subsequent writes fail
   353			fmt.Fprint(out, "ccc") // dropped by the sticky writer
   354		})
   355		if !errors.Is(err, errVitalityTestOutput) {
   356			t.Fatalf("writeText err = %v, want %v", err, errVitalityTestOutput)
   357		}
   358		// Two distinct Writes landed before the failure and the third was dropped:
   359		// a buffer-then-write implementation would issue a single Write of the whole
   360		// body (and emit nothing at all once a later write fails).
   361		if len(w.writes) != 2 || w.writes[0] != "aaa" || w.writes[1] != "bbb" {
   362			t.Fatalf("writeText did not stream incrementally: %#v", w.writes)
   363		}
   364	}
