500	func TestVitalityCompactionIsIdempotentAndCrashSafe(t *testing.T) {
501		brainDir := t.TempDir()
502		branch := "main"
503		now := time.Date(2026, 6, 8, 12, 0, 0, 0, time.UTC)
504		events := []vitalityEvent{
505			// Timestamps are intentionally out of order to verify both range endpoints.
506			{Type: vitalityEventServed, FactID: "fact:a", At: now.Add(time.Minute), Surface: "query", Branch: branch},
507			{Type: vitalityEventServed, FactID: "fact:a", At: now, Surface: "recall", Branch: branch},
508			{Type: vitalityEventServed, FactID: "fact:b", At: now, Surface: "brief", Branch: branch},
509		}
510		if err := appendVitalityEvents(brainDir, branch, events); err != nil {
511			t.Fatalf("append: %v", err)
512		}
513		logPath := filepath.Join(brainDir, filepath.FromSlash(factsVitalityLogRelPath(branch)))
514		logBefore, err := os.ReadFile(logPath)
515		if err != nil {
516			t.Fatalf("read log: %v", err)
517		}
518	
519		if _, _, err := compactVitality(brainDir, branch); err != nil {
520			t.Fatalf("compact: %v", err)
521		}
522		rollupPath := filepath.Join(brainDir, filepath.FromSlash(factsVitalityRollupRelPath(branch)))
523		first, err := os.ReadFile(rollupPath)
524		if err != nil {
525			t.Fatalf("read rollup: %v", err)
526		}
527		if info, err := os.Stat(logPath); err != nil || info.Size() != 0 {
528			t.Fatalf("log not truncated after compaction: %v (size %d)", err, info.Size())
529		}
530	
531		// Idempotence: recompacting with nothing new is a byte-identical no-op.
532		if _, _, err := compactVitality(brainDir, branch); err != nil {
533			t.Fatalf("recompact: %v", err)
534		}
535		second, err := os.ReadFile(rollupPath)
536		if err != nil {
537			t.Fatalf("reread rollup: %v", err)
538		}
539		if !bytes.Equal(first, second) {
540			t.Fatalf("recompaction changed the rollup:\n%s\nvs\n%s", first, second)
541		}
542		var afterFirst vitalityRollup
543		if err := json.Unmarshal(first, &afterFirst); err != nil {
544			t.Fatalf("parse rollup: %v", err)
545		}
546		if afterFirst.Facts["fact:a"].Served != 2 || afterFirst.Facts["fact:b"].Served != 1 {
547			t.Fatalf("rollup counts = %+v", afterFirst.Facts)
548		}
549		if afterFirst.Facts["fact:a"].LastSurface != "query" {
550			t.Fatalf("last surface = %q", afterFirst.Facts["fact:a"].LastSurface)
551		}
552		if got := afterFirst.Facts["fact:a"]; !got.FirstServed.Equal(now) || !got.LastServed.Equal(now.Add(time.Minute)) {
553			t.Fatalf("fact:a service range = %s..%s", got.FirstServed, got.LastServed)
554		}
555	
556		// Crash safety: reconstruct the state after phase 1 of compaction (rollup
557		// written with the absorbed-log marker, truncation never happened) and
558		// verify recompaction does not double-count the log.
559		crashed := afterFirst
560		crashed.Log = vitalityLogMarker{AbsorbedBytes: int64(len(logBefore)), AbsorbedSHA256: vitalityContentSHA(logBefore)}
561		if err := writeVitalityRollup(brainDir, branch, crashed); err != nil {
562			t.Fatalf("write crashed rollup: %v", err)
563		}
564		if err := appendBrainRelativeFile(brainDir, factsVitalityLogRelPath(branch), logBefore); err != nil {
565			t.Fatalf("restore log: %v", err)
566		}
567		recovered, stats, err := compactVitality(brainDir, branch)
568		if err != nil {
569			t.Fatalf("recover compact: %v", err)
570		}
571		if stats.NewEvents != 0 {
572			t.Fatalf("already-absorbed events re-counted: %+v", stats)
573		}
574		if recovered.Facts["fact:a"].Served != 2 || recovered.Facts["fact:b"].Served != 1 {
575			t.Fatalf("double-counted after crash recovery: %+v", recovered.Facts)
576		}
577		if info, err := os.Stat(logPath); err != nil || info.Size() != 0 {
578			t.Fatalf("log not truncated after recovery: %v", err)
579		}
580		final, err := os.ReadFile(rollupPath)
581		if err != nil {
582			t.Fatalf("read recovered rollup: %v", err)
583		}
584		if !bytes.Equal(first, final) {
585			t.Fatalf("crash recovery changed the rollup:\n%s\nvs\n%s", first, final)
586		}
587	}
