    15	// CURRENT branch's tip — so the stored fact reads "on release, evidenced by
    16	// <a commit that is only on main>". `verify` cannot catch it: verifyCommitUncached
    17	// accepts reachability from ANY local ref, so the fabricated pairing is
    18	// reported as verified forever.
    19	func TestRememberAnchorsToTheBranchItFilesTheFactOn(t *testing.T) {
    20		fixture := newEntityIndexFixture(t)
    21		// The working tree is on `main`, whose tip is commit B.
    22		fixture.runner.responses[fakeCommandKey("git", "rev-parse", "HEAD")] = fakeCommandResponse{stdout: entityFixtureCommitB + "\n"}
    23		// `release` is a real local branch pointing somewhere else entirely.
    24		fixture.runner.responses[fakeCommandKey("git", "rev-parse", "--verify", "release^{commit}")] = fakeCommandResponse{stdout: releaseBranchTip + "\n"}
    25	
    26		fixture.run(t, "remember", "--branch", "release", "--path", "architecture.data.flow", "The release branch pins the v1 payload schema.")
