    28		facts, err := loadFacts(fixture.storage.BrainDir, "release")
    29		if err != nil {
    30			t.Fatalf("load facts: %v", err)
    31		}
    32		if len(facts) != 1 || len(facts[0].Provenance) != 1 {
    33			t.Fatalf("stored facts = %+v", facts)
    34		}
    35		got := facts[0].Provenance[0].Commit
    36		if got == entityFixtureCommitB {
    37			t.Fatalf("a fact filed on `release` cites %s, the tip of the CURRENT branch (main)", got)
    38		}
    39		if got != releaseBranchTip {
    40			t.Fatalf("anchor commit = %q, want the tip of `release` (%s)", got, releaseBranchTip)
    41		}
