   169	// TestDoctorFailsOnUnreadableSemanticStore is the gate defect. "file is not a
   170	// database" is the strongest broken signal this tool has, and it was reported
   171	// as a warning, so the default `--fail-on error` gate exited 0 on a corrupt
   172	// brain.
   173	func TestDoctorFailsOnUnreadableSemanticStore(t *testing.T) {
   174		report := staleReport{Severity: "unsafe", Axes: map[string]staleAxis{
   175			"snapshot":              {State: "ok", Detail: "semantic/snapshots/a/snapshot.ndjson"},
   176			"store":                 {State: "unsafe", Detail: "validate semantic sqlite integrity: file is not a database (26)"},
   177			"head":                  {State: "ok"},
   178			"branch_tip":            {State: "ok"},
   179			"worktree":              {State: "clean"},
   180			"provider":              {State: "ok", Detail: "entire-graph 1.2.3"},
   181			"semantic_completeness": {State: "ok"},
   182		}}
   183		findings := semanticDoctorFindings(report)
   184		byName := doctorFindingsByName(findings)
   185		semantic, ok := byName["semantic"]
   186		if !ok {
   187			t.Fatalf("doctor dropped the semantic finding: %+v", findings)
   188		}
   189		if semantic.State != "error" {
   190			t.Fatalf("semantic state = %q for an unreadable store, want error: %+v", semantic.State, semantic)
   191		}
   192		if semantic.scope() != doctorScopeBrain {
   193			t.Fatalf("semantic scope = %q, want %q", semantic.scope(), doctorScopeBrain)
   194		}
   195		if !strings.Contains(semantic.Detail, "file is not a database") {
   196			t.Fatalf("semantic detail lost the reason: %q", semantic.Detail)
   197		}
   198		if err := doctorGateFailure(doctorReport{Checks: findings}, doctorFailOnError); err == nil {
   199			t.Fatalf("the default --fail-on error gate must fire on an unreadable semantic store")
   200		}
   201	}
