		message := mcpScopeErrorMessage(t, response)
		if !strings.Contains(message, mcpAllowCrossRepoEnv) {
			t.Fatalf("%s refusal must name the opt-in gate %s: %s", tc.tool, mcpAllowCrossRepoEnv, message)
