	}
	h.commitAll("codex probe turn")
	if !h.headHasCheckpointTrailer() {
		t.Fatal("Codex work committed without an Entire-Checkpoint trailer")
	}
	h.brain("refresh", "--semantic=false")
	h.assertRecallJourney("KIWI_E2E_5")
}

