	if err := json.Unmarshal([]byte(mcpRowsPayload(t, "results", 4000)), &doc); err != nil {
		t.Fatalf("decode payload: %v", err)
	}
	doc["pagination"] = map[string]any{"limit": 10000, "offset": 0, "count": 4000}
	payload, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
