		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			raw := json.RawMessage("null")
			if tc.call != nil {
				data, err := json.Marshal(tc.call)
				if err != nil {
					t.Fatalf("marshal call: %v", err)
				}
				raw = data
			}
			_, err := handleMCPToolCall(context.Background(), Options{}, raw)
			if err == nil {
				t.Fatalf("%s was accepted", tc.name)
