	}
	if _, _, err := readMCPMessage(bufio.NewReader(strings.NewReader("Content-Length: -1\r\n\r\n"))); err == nil || !strings.Contains(err.Error(), "non-negative") {
		t.Fatalf("negative frame err = %v", err)
	}
}

