		frameMCP(`{"jsonrpc":"2.0","id":3,"method":"tools/call","params":{"name":"brain_workspace_regressions","arguments":{"workspace":"related","query":"fix scopeBaseRef base scope","location_only":true}}}`)
	var out bytes.Buffer
